/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D = globalThis.RA.D;
const q = (w,n,s,p,a,b,c,x) => ({id:w+'.q'+n,senseId:w+'.s'+s,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const m = (wrong,right,reason) => ({errorType:'meaning',wrong,right,reason});
const c = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const e = (origin,w) => ({origin,prefix:null,root:null,suffix:null,source:'Etymonline, https://www.etymonline.com/word/'+encodeURIComponent(w.toLowerCase())});

/* A11 fixed manifest: 80 individually authored entries, saved in four verified 20-word checkpoints. */
D('breakwater',{etymology:e('breakwater 是 break + water 的英语复合词，字面为削弱水浪的结构；作为港口术语指挡浪堤。','breakwater'),contexts:[c('breakwater.s1','港口工程','The harbor authority extended the breakwater after winter storms sent heavy waves over the old wall and damaged several moored boats.','冬季风暴把巨浪卷过旧堤并损坏数艘系泊船后，港务局加长了防波堤。','The harbor authority extended the breakwater / after winter storms sent heavy waves over the old wall / and damaged several moored boats.','breakwater 是 extend 的宾语；after 引出此前发生的风暴。','结构挡在港口外削弱海浪，正是防波堤义。')],mistakes:[m('The breakwater increased the force of every wave entering the harbor.','The breakwater reduced the force of every wave entering the harbor.','防波堤的功能是削弱波浪；将 increased 改为 reduced 即可。')],quiz:[q('breakwater',1,1,'Why did engineers build a breakwater outside the harbor?','to reduce the force of incoming waves','to make the water deeper','to store drinking water','breakwater 挡在港外以削弱海浪。'),q('breakwater',2,1,'A fishing boat is safest behind a breakwater during?','a storm with high waves','a dry day on land','a quiet indoor meeting','防波堤为船只提供挡浪保护。'),q('breakwater',3,1,'Which structure is a breakwater?','a barrier that shelters a port from waves','a channel that carries fresh water uphill','a floating sign that marks a beach shop','breakwater 是港口外的挡浪屏障。'),q('breakwater',4,1,'In breakwater, break refers to the structure’s ability to?','break or weaken wave action','break a boat into pieces','break the rules of navigation','这里 break 表示削减浪势。')]});
D('breathable',{etymology:e('breathable 由 breathe 加形容词后缀 -able 构成，表示空气或水汽能够通过，或材料适合呼吸；衣料义是常见用法。','breathable'),contexts:[c('breathable.s2','户外服装','For the summer hike, Mira wore a breathable shirt that let sweat vapor escape while still blocking the light rain.','夏季徒步时，米拉穿了一件透气衬衫，既能让汗汽散出，又能挡住小雨。','For the summer hike / Mira wore a breathable shirt / that let sweat vapor escape / while still blocking the light rain.','breathable 修饰 shirt；that 引导定语从句说明面料性能。','此处指布料允许水汽逸出，符合 s2。')],mistakes:[m('The breathable rain jacket trapped all sweat vapor against the skin and allowed no air exchange.','The nonbreathable rain jacket trapped all sweat vapor against the skin and allowed no air exchange.','会困住汗汽且不透气的衣物不是 breathable；改为 nonbreathable。')],quiz:[q('breathable',1,2,'A breathable hiking fabric is designed to let what escape?','water vapor from perspiration','the jacket’s stitching','the wearer’s body heat as liquid','衣料义 breathable 指汗汽可以透出。'),q('breathable',2,1,'Which product would likely be labeled breathable?','a running shirt that releases moisture vapor','a sealed plastic bag with no airflow','a glass bottle for storing oil','透气跑步衫符合面料义。'),q('breathable',3,1,'In a medical context, breathable air is air that is?','safe and suitable to inhale','too toxic to enter the lungs','made entirely of liquid','空气义指可以安全吸入。'),q('breathable',4,2,'A membrane described as breathable allows?','air or vapor to pass through','solid rocks to dissolve instantly','sound to become visible','breathable 的材料义强调空气或水汽通过。')]});
D('breathing',{etymology:e('breathing 是动词 breathe 的 -ing 形式；作名词指吸入和呼出空气的过程，也可作形容词表示仍活着。','breathing'),contexts:[c('breathing.s1','急救训练','The instructor watched the patient’s chest for several seconds, checking whether normal breathing had resumed before beginning the next step.','开始下一步前，教练观察患者胸部数秒，确认正常呼吸是否恢复。','The instructor watched the patient’s chest for several seconds / checking whether normal breathing had resumed / before beginning the next step.','breathing 作名词，normal 修饰该过程；whether 引导间接疑问。','语境指吸气与呼气的生理过程，符合 s1。')],mistakes:[m('The medic checked the patient’s breathing and found that no air moved in or out, so the patient was breathing normally.','The medic checked the patient’s breathing and found that no air moved in or out, so the patient was not breathing.','没有空气进出不能称正常呼吸；删去相互矛盾的 normally。')],quiz:[q('breathing',1,1,'A nurse checks a patient’s breathing to see whether the patient is?','drawing air in and letting it out','digesting a meal','hearing a quiet sound','breathing 名词指吸入和呼出空气。'),q('breathing',2,2,'A breathing person in the old sense is?','alive','painted on a wall','already buried','形容词义 breathing 可表示仍活着。'),q('breathing',3,1,'After running, slow breathing means?','air is moving in and out of the lungs','the runner has stopped hearing','the runner is counting footsteps','呼吸是肺部空气进出的过程。'),q('breathing',4,1,'Which sentence uses breathing as a process noun?','Her breathing became steady after she rested.','The breathing portrait hung in the hall.','They breathing the air yesterday.','此句 breathing 表示呼吸过程。')]});
D('breathless',{etymology:e('breathless 由 breath + -less（缺少、没有）构成，字面“气息不畅”；可指气喘，也可比喻激动或紧张得屏息。','breathless'),contexts:[c('breathless.s2','悬疑阅读','The final chapter left readers breathless as the missing key appeared in the locked room just before the clock struck midnight.','最后一章让读者紧张得屏住呼吸：午夜钟声响起前，失踪的钥匙竟出现在锁着的房间里。','The final chapter left readers breathless / as the missing key appeared in the locked room / just before the clock struck midnight.','leave + 宾语 + 形容词表示使人处于某状态；as 引出情境。','此处是因悬念而紧张屏息的比喻义 s2。')],mistakes:[m('After the slow walk, he was breathless because he could breathe easily without any effort.','After the steep climb, he was breathless because he struggled to catch his breath.','breathless 描写气喘或屏息状态，与轻松呼吸相矛盾。')],quiz:[q('breathless',1,2,'A breathless audience at a tense finish is likely?','holding its breath with excitement','sleeping through the event','uninterested in the result','比喻义指紧张兴奋得屏息。'),q('breathless',2,1,'After sprinting uphill, someone may feel breathless because?','it is difficult to breathe normally','the air has turned into water','the person has stopped using legs','体力消耗后 breathless 指气喘。'),q('breathless',3,2,'Which scene could leave viewers breathless?','a suspenseful rescue seconds before disaster','a routine list read in a monotone','an empty screen with no sound','强烈悬念可使观众紧张屏息。'),q('breathless',4,1,'Choose the natural cause of a breathless runner.','She ran up six flights of stairs.','She sat quietly and rested all afternoon.','She drank a glass of water at a desk.','剧烈跑楼梯容易气喘。')]});
D('breathtaking',{etymology:e('breathtaking 由 breath + take + -ing 构成，字面为“令人屏住呼吸”，引申为美得惊人或刺激得令人屏息。','breathtaking'),contexts:[c('breathtaking.s1','自然景观','At dawn, the hikers reached the ridge and saw a breathtaking view of the glacier glowing pink beneath the first sunlight.','黎明时，徒步者到达山脊，看见冰川在第一缕阳光下泛着粉色，景色令人叹为观止。','At dawn / the hikers reached the ridge / and saw a breathtaking view of the glacier / glowing pink beneath the first sunlight.','breathtaking 修饰 view；glowing 分词短语描写冰川景象。','美丽景色令人生出惊叹，符合 s1。')],mistakes:[m('The breathtaking view was dull and ordinary, so nobody noticed it.','The unremarkable view was dull and ordinary, so nobody noticed it.','令人惊叹的景色不会同时被描述为平淡无奇；改用 unremarkable。')],quiz:[q('breathtaking',1,1,'A breathtaking view is one that is?','so beautiful it inspires wonder','too small to see','ordinary and easy to forget','breathtaking 常形容美得惊人。'),q('breathtaking',2,2,'A breathtaking race finish may be?','so exciting that viewers feel suspense','a slow event with no uncertainty','a race canceled before it starts','刺激紧张也可令人屏息。'),q('breathtaking',3,1,'Which is a natural use of breathtaking?','a breathtaking panorama of the mountains','a breathtakingly broken pencil with no event','a breathtaking calendar date only','breathtaking 常修饰景色或景象。'),q('breathtaking',4,1,'The word literally suggests that something?','takes your breath away','makes breathing unnecessary forever','measures the speed of air','字面意象是令人屏息。')]});
D('breech',{etymology:e('breech 经古英语 brēc“裤子、臀部”发展而来；现代可指枪炮后膛，也保留臀部朝前的胎位义。','breech'),contexts:[c('breech.s1','枪械结构','Before cleaning the rifle, the instructor opened the breech and checked that no cartridge remained in the rear of the barrel.','清洁步枪前，教官打开枪膛后部，检查枪管后膛中是否还留有子弹。','Before cleaning the rifle / the instructor opened the breech / and checked that no cartridge remained in the rear of the barrel.','breech 指枪管后膛；that 从句作 checked 的宾语。','弹药从枪管后端装入的位置是 breech 的枪械义 s1。')],mistakes:[m('The bullet exits through the breech at the front end of the barrel.','The bullet exits through the muzzle at the front end of the barrel.','枪口是 muzzle；breech 是枪管后端。')],quiz:[q('breech',1,1,'The breech of a gun is at the?','rear end of the barrel where it is loaded','front opening where the bullet exits','handle used to aim','breech 指枪管后部的装弹处。'),q('breech',2,2,'A baby in breech position is coming?','buttocks or feet first','head first','sideways through a window','breech 也指臀位或足先露的胎位。'),q('breech',3,1,'Which part would a shooter inspect to check the chamber?','the breech','the trigger guard only','the front sight','枪膛及装弹处位于 breech。'),q('breech',4,1,'Select the correct contrast.','Muzzle is the front; breech is the rear.','Muzzle is the rear; breech is the stock.','Both words mean the trigger.','枪口 muzzle 与后膛 breech 相对。')]});
D('breeding',{etymology:e('breeding 是 breed 的 -ing 形式；名词可指培育繁殖，也可指教养、礼貌举止，后者源于“养育、培养”的引申。','breeding'),contexts:[c('breeding.s2','动物育种','Careful breeding of the dairy herd over several generations increased milk yield without sacrificing the animals’ resistance to disease.','经过几代谨慎选育，奶牛群的产奶量提高，同时没有牺牲其抗病能力。','Careful breeding of the dairy herd over several generations / increased milk yield / without sacrificing the animals’ resistance to disease.','breeding 作名词，of 引出选育对象；without 后接动名词。','通过繁殖选育获得特征，符合 s2。')],mistakes:[m('The breeder improved the herd by breeding animals randomly and selecting none for useful traits.','The breeder improved the herd by selective breeding for useful traits.','有目的的育种要选择目标性状；随机繁殖且不筛选与改良相矛盾。')],quiz:[q('breeding',1,2,'Selective breeding aims to?','produce offspring with chosen useful traits','teach adult animals table manners','prevent all animals from reproducing','育种通过选配获得目标性状。'),q('breeding',2,1,'A person described as having good breeding may show?','polite, well-mannered behavior','a fast running speed','a preference for wet weather','good breeding 可指良好教养。'),q('breeding',3,2,'Which activity is animal breeding?','choosing parent cattle to improve a herd','painting a barn door','weighing a sack of grain','breed 动物的名词形式指繁殖选育。'),q('breeding',4,1,'Plant breeding would most directly involve?','crossing plants to develop desired varieties','storing vegetables in a cellar','watering a lawn at noon','plant breeding 指培育新品种。')]});
D('brevity',{etymology:e('brevity 借自拉丁语 brevitas（简短），源自 brevis“短”；英语中可指表达简练，也可指时间短暂。','brevity'),contexts:[c('brevity.s1','编辑写作','The editor praised the memo’s brevity: it stated the decision, gave one reason, and ended before the meeting began.','编辑称赞备忘录简洁：说明决定、给出一个理由，并在会议开始前就结束了。','The editor praised the memo’s brevity / it stated the decision / gave one reason / and ended before the meeting began.','brevity 是 praised 的宾语；冒号后列举简短的表现。','少量文字清楚表达要点，体现表达简练义 s1。')],mistakes:[m('The report’s brevity came from forty pages of repeated explanations and long digressions.','The report’s length came from forty pages of repeated explanations and long digressions.','大量重复和离题内容说明篇幅冗长，而非 brevity。')],quiz:[q('brevity',1,1,'A writer who values brevity tries to?','express the point in few words','repeat each point several times','add unrelated details','brevity 指用语简洁。'),q('brevity',2,2,'The brevity of a visit refers to its?','short duration','high cost','large number of guests','时间义 brevity 是短暂。'),q('brevity',3,1,'Which sentence demonstrates brevity?','“Approved. Start Monday.”','A six-page paragraph repeating the same request.','A speech that never reaches its subject.','用极少文字表达清楚，体现简练。'),q('brevity',4,1,'The familiar saying “brevity is the soul of wit” praises?','concise expression','endless explanation','silent reading only','这句话赞扬简洁有力的表达。')]});
D('brewer',{etymology:e('brewer 由 brew（酿造）加施事者后缀 -er 构成，可指酿啤酒的人，也可指酿造企业。','brewer'),contexts:[c('brewer.s1','酿造业','The brewer tested a small batch of pale ale, adjusted the hop balance, and recorded the recipe before the brewery scaled up production.','酿酒师试酿一小批淡色艾尔，调整啤酒花比例，并在酒厂扩大生产前记下配方。','The brewer tested a small batch of pale ale / adjusted the hop balance / and recorded the recipe / before the brewery scaled up production.','brewer 是执行酿造工作的主体；before 引出量产之前。','人物义 brewer 指酿啤酒的人。')],mistakes:[m('The brewer repaired the ship’s sails and never worked with beer or fermentation.','The sailmaker repaired the ship’s sails and never worked with beer or fermentation.','修帆的是 sailmaker；brewer 的工作是酿造啤酒。')],quiz:[q('brewer',1,1,'A brewer’s central work is to?','make beer through brewing','repair a ship’s sails','measure a courtroom sentence','brewer 指酿酒者或酿酒企业。'),q('brewer',2,1,'Who would adjust the hops in an ale recipe?','a brewer','a lighthouse keeper','a tailor','啤酒花配方属于酿造工作。'),q('brewer',3,1,'In “the brewer released a new lager,” brewer names?','the person or company making the beer','the person drinking it','the shop selling only bread','brewer 可指酿造者或酿造公司。'),q('brewer',4,1,'The suffix -er in brewer marks?','the person who performs an activity','a place where grain is stored','a quality meaning blue','-er 表示从事 brew 的人。')]});
D('brewery',{etymology:e('brewery 由 brew（酿造）加表示场所的 -ery 构成，指酿制啤酒的厂房或企业。','brewery'),contexts:[c('brewery.s1','工厂参观','During the tour, the guide showed visitors the brewery’s copper kettles, fermentation tanks, and bottling line before leading them to the tasting room.','参观途中，导游先带游客看酒厂的铜锅、发酵罐和装瓶线，之后才领他们去品尝室。','During the tour / the guide showed visitors the brewery’s copper kettles, fermentation tanks, and bottling line / before leading them to the tasting room.','brewery 所有格修饰生产设备；before leading 省略主语 the guide。','发酵、煮制、装瓶设备构成啤酒厂生产场所。')],mistakes:[m('The brewery was a library where no beer was brewed or stored.','The library was a place where no beer was brewed or stored.','不进行啤酒酿造的图书馆不是 brewery。')],quiz:[q('brewery',1,1,'What happens in a brewery?','beer is made','books are bound','passengers board a train','brewery 是酿造啤酒的场所。'),q('brewery',2,1,'Fermentation tanks are likely found at a?','brewery','shoe repair shop','post office','发酵罐是啤酒生产设备。'),q('brewery',3,1,'A brewery tour would most likely explain?','how beer is brewed and bottled','how court cases are appealed','how to grow a forest','酒厂导览介绍酿造和装瓶流程。'),q('brewery',4,1,'The ending -ery in brewery helps name?','a place or business associated with brewing','a person who drinks water','a past-tense action','brewery 指从事酿造的工厂或企业。')]});
D('brewster',{etymology:e('brewster 是 brew 加古老职业后缀 -ster 的女性酿酒者称呼，历史上尤指酿造啤酒或麦酒的人；现代多见于姓氏。','brewster'),contexts:[c('brewster.s1','中世纪城镇','In the town’s medieval records, the brewster paid a small market fee for selling ale beside the mill, while the baker sold loaves nearby.','在镇上的中世纪记录中，女酿酒者因在磨坊旁卖麦酒缴了一小笔集市费，面包师则在附近卖面包。','In the town’s medieval records / the brewster paid a small market fee for selling ale beside the mill / while the baker sold loaves nearby.','brewster 是历史职业名词；for selling 说明缴费原因。','历史记录中的 ale 销售者是酿酒女性这一旧职业义。')],mistakes:[m('The brewster’s trade was making ale, but the record says she brewed no drink and only repaired shoes.','The cobbler’s trade was repairing shoes, but the record says she brewed ale.','修鞋职业是 cobbler；brewster 的历史职业与酿酒有关。')],quiz:[q('brewster',1,1,'Historically, a brewster was a person who?','brewed ale or beer','made maps for sailors','repaired shoes','brewster 是历史上的酿酒者称呼。'),q('brewster',2,1,'A medieval record listing ale sales might mention a?','brewster','broom maker who never brewed','ship’s navigator','brewster 与麦酒酿造相关。'),q('brewster',3,1,'Which activity fits a brewster’s historical occupation?','fermenting grain to make ale','carving a stone road sign','weaving a fishing net','酿造谷物酒符合旧时职业。'),q('brewster',4,1,'The word is now also encountered as?','a surname','a unit of temperature','a name for a sea bird','brewster 现代常见作姓氏。')]});
D('bribery',{etymology:e('bribery 由 bribe 加名词后缀 -ery 构成，表示行贿、受贿或以不正当利益影响决策的行为。','bribery'),contexts:[c('bribery.s1','公共采购','Investigators uncovered bribery when a contractor’s private payments to the procurement officer matched the dates of unusually favorable bids.','调查人员发现承包商向采购官员的私下付款日期与异常有利的投标时间吻合，因而揭露了贿赂行为。','Investigators uncovered bribery / when a contractor’s private payments to the procurement officer / matched the dates of unusually favorable bids.','bribery 作不可数名词；when 引出发现问题的证据。','以私下付款换取采购优惠，是行贿影响决策。')],mistakes:[m('The officer rejected every gift and reported the offer, proving that he accepted bribery.','The officer rejected every gift and reported the offer, proving that he resisted bribery.','拒绝并举报贿赂表明抵制，而非接受贿赂。')],quiz:[q('bribery',1,1,'Bribery occurs when someone?','offers or accepts an improper reward to influence a decision','pays a published fee for a service','gives a friend a birthday card','bribery 指用不正当利益影响决策。'),q('bribery',2,1,'Which is evidence of possible bribery?','secret cash paid before an official awards a contract','an invoice paid at the listed public price','a free public safety notice','秘密付款换合同可能是贿赂。'),q('bribery',3,1,'A firm convicted of bribery may have?','improperly paid an official for favorable treatment','followed every transparent bidding rule','donated books with no requested favor','以私款换取优待符合贿赂行为。'),q('bribery',4,1,'Bribery is generally considered?','corrupt and unlawful conduct','a neutral way to publish prices','a type of weather forecast','bribery 通常是腐败且违法的行为。')]});
D('brightly',{etymology:e('brightly 是形容词 bright 加副词后缀 -ly，意为发出明亮光线，也可描述生动欢快的神情或声音。','brightly'),contexts:[c('brightly.s2','谈话神态','When the shy child recognized her aunt, she smiled brightly and began telling everyone about the school play.','害羞的孩子认出姑妈后，露出灿烂笑容，并开始向大家讲学校演出的事。','When the shy child recognized her aunt / she smiled brightly / and began telling everyone about the school play.','brightly 修饰 smiled，说明微笑的方式；begin 后接动名词。','明朗欢快的微笑体现副词的神采义 s2。')],mistakes:[m('The lamp shone brightly, but the room remained completely dark because no light came from it.','The lamp failed to shine, and the room remained completely dark because no light came from it.','若灯发出明亮光线，房间不会因它完全没有光；删去互相矛盾的 brightly。')],quiz:[q('brightly',1,1,'If a lamp shines brightly, it gives?','a strong, clear light','no light at all','a low musical note','brightly 的光线义表示明亮地。'),q('brightly',2,2,'A child who smiles brightly looks?','cheerful and lively','angry and exhausted','invisible','brightly 可描述欢快的神态。'),q('brightly',3,1,'Which uses brightly to describe color?','The flags were painted brightly for the parade.','The flags were buried silently underground.','The flags tasted brightly of salt.','颜色明快也可用 brightly 描述。'),q('brightly',4,1,'Choose the sentence where brightly modifies a verb.','The stars glowed brightly above the camp.','The brightly of stars was measured.','Brightly stars are a kind of planet.','brightly 修饰动词 glowed。')]});
D('brilliantly',{etymology:e('brilliantly 由 brilliant 加副词后缀 -ly 构成；可表示才智或技巧出色，也可表示光芒耀眼。','brilliantly'),contexts:[c('brilliantly.s1','竞赛解题','Leah solved the final puzzle brilliantly by noticing that the supposedly random symbols followed the same repeating pattern.','莉娅巧妙地解开最后一道谜题，她发现那些看似随机的符号遵循同一个重复规律。','Leah solved the final puzzle brilliantly / by noticing / that the supposedly random symbols followed the same repeating pattern.','brilliantly 修饰 solved；by + 动名词说明解题办法。','凭敏锐观察出色地解题，符合才智出众义 s1。')],mistakes:[m('The analyst brilliantly missed the obvious pattern and gave an answer that contradicted every clue.','The analyst carelessly missed the obvious pattern and gave an answer that contradicted every clue.','忽略明显规律并与线索矛盾不是 brilliant 的出色表现。')],quiz:[q('brilliantly',1,1,'A student who solves a puzzle brilliantly does so?','with exceptional skill or intelligence','by ignoring every clue','only after copying a wrong answer','才智义 brilliantly 指表现出色。'),q('brilliantly',2,2,'A diamond reflecting sunlight brilliantly would?','shine with strong light','absorb all light and look black','make no visible reflection','光线义表示耀眼地闪光。'),q('brilliantly',3,1,'Which sentence uses brilliantly for skill?','The engineer brilliantly found a simpler design.','The engineer slept brilliantly in a dark room.','The design was brilliantly absent from the plan.','simpler design 的巧妙发现体现才智出色。'),q('brilliantly',4,1,'A brilliantly lit stage is?','illuminated very brightly','left in complete darkness','painted with no color or light','修饰 lit 时表示光线很亮。')]});
D('brine',{etymology:e('brine 经古英语、古诺斯语相关形式，源自日耳曼语中表示盐水的词；既可指浓盐水，也可作动词表示用盐水浸泡食物。','brine'),contexts:[c('brine.s2','烹饪保存','To keep the turkey moist, the cook brined it overnight in cold water with salt, herbs, and crushed peppercorns.','为让火鸡保持多汁，厨师把它在加盐、香草和碎胡椒粒的冷水中浸泡了一夜。','To keep the turkey moist / the cook brined it overnight in cold water / with salt, herbs, and crushed peppercorns.','brined 是及物动词过去式；to keep 表目的。','把肉放进盐水中腌浸，符合 brine 的动词义 s2。')],mistakes:[m('The recipe says to brine the fish, so the cook leaves it dry in an empty bowl with no salt water.','The recipe says to brine the fish, so the cook soaks it in salted water.','brine 作动词要求盐水浸泡；完全干放与指令相反。')],quiz:[q('brine',1,2,'To brine vegetables means to?','soak them in salty water','dry them in hot sand','cover them with plain paper','动词 brine 指用盐水浸泡。'),q('brine',2,1,'A jar of brine contains?','water with a high concentration of salt','pure oil with no water','dry sugar crystals only','名词 brine 是盐水。'),q('brine',3,2,'Why might a cook brine meat before roasting?','to season it and help it retain moisture','to remove all flavor and water','to turn it into a metal','盐水腌制可调味并帮助保持水分。'),q('brine',4,1,'Which liquid is brine?','salty water used to preserve food','fresh unsalted cream','a bottle of cooking oil','盐水是 brine。')]});
D('bring about',{etymology:e('bring about 是 bring + 副词/介词 about 构成的短语动词，about 带来“促成结果”的用法，整体表示使变化或事件发生。','bring about'),contexts:[c('bring about.s1','城市交通','The new bus lanes brought about a noticeable drop in commute times because buses no longer had to wait behind cars.','新设公交专用道使通勤时间明显缩短，因为公交车不再需要排在汽车后面等候。','The new bus lanes brought about a noticeable drop in commute times / because buses no longer had to wait behind cars.','bring about 是及物短语动词，宾语为 a drop；过去式 brought。','公交专用道促成通勤时间变化，符合“使发生”义。')],mistakes:[m('The policy brought about the delays, yet it caused no changes or consequences of any kind.','The policy brought about the delays, creating a clear consequence for commuters.','bring about 表示造成结果，不能同时声称没有任何结果。')],quiz:[q('bring about',1,1,'To bring about a change is to?','cause the change to happen','carry an object around a room','prevent the change from occurring','bring about 表示促成、导致某事发生。'),q('bring about',2,1,'Which could bring about fewer accidents?','better street lighting at dangerous crossings','removing every traffic signal','hiding the road signs','改善照明可能导致事故减少。'),q('bring about',3,1,'Complete: “The agreement ___ a peaceful settlement.”','brought about','brought after','brought about to','短语 bring about 后直接接结果作宾语。'),q('bring about',4,1,'In “The reform brought about progress,” brought about means?','produced or caused','carried away','asked about','短语在句中表示产生进步。')]});
D('briny',{etymology:e('briny 由 brine（盐水）加形容词后缀 -y 构成，表示咸的、带海水气味的或属于海洋的。','briny'),contexts:[c('briny.s1','海岸观察','A briny wind blew across the pier, leaving a faint salt smell on the visitors’ coats as fishing boats returned to shore.','带着海盐气息的风吹过码头，渔船返岸时，游客的外套上留下淡淡咸味。','A briny wind blew across the pier / leaving a faint salt smell on the visitors’ coats / as fishing boats returned to shore.','briny 修饰 wind；leaving 分词结构描述风带来的结果。','海风带有咸味和海洋气息，符合 briny。')],mistakes:[m('The briny soup contained no salt at all and tasted completely sweet.','The unsalted soup contained no salt at all and tasted completely sweet.','briny 表示咸的；无盐且纯甜的汤不适用此词。')],quiz:[q('briny',1,1,'A briny smell near the shore is likely?','salty and reminiscent of seawater','sweet like fresh berries','smoky like a fireplace','briny 表示咸或带海水气味。'),q('briny',2,1,'Which description suits briny water?','water with a strong salty taste','distilled water with no dissolved salt','frozen milk','briny water 带有明显盐分。'),q('briny',3,1,'A sailor might call ocean air briny because it?','carries a salty sea scent','smells exactly like fresh bread','contains no connection to the sea','海风咸味明显，所以可称 briny。'),q('briny',4,1,'The adjective briny comes from a word for?','salt water','dry wood','bright light','briny 派生于 brine 盐水。')]});
D('brisbane',{etymology:e('Brisbane 是澳大利亚昆士兰州首府的专名，以苏格兰军官兼新南威尔士州总督 Thomas Brisbane 命名；不要把专名误解为普通地貌词。','brisbane'),contexts:[c('brisbane.s1','澳大利亚地理','During her exchange year in Brisbane, Nia took the CityCat ferry along the river and visited the state museum on a rainy afternoon.','交换学习期间，妮娅在布里斯班乘城市猫渡轮沿河而行，并在一个雨天下午参观了州立博物馆。','During her exchange year in Brisbane / Nia took the CityCat ferry along the river / and visited the state museum / on a rainy afternoon.','专名 Brisbane 作地点状语；take a ferry 指乘渡船。','河流渡轮和州博物馆定位了澳大利亚昆士兰州首府。')],mistakes:[m('Brisbane is the capital of Queensland in northern Australia, so the traveler booked a flight to Canada.','Brisbane is the capital of Queensland in Australia, so the traveler booked a domestic flight.','布里斯班位于澳大利亚昆士兰州，不在加拿大。')],quiz:[q('brisbane',1,1,'Brisbane is the capital of which Australian state?','Queensland','Tasmania','Western Australia','布里斯班是昆士兰州首府。'),q('brisbane',2,1,'A visitor in Brisbane is in?','eastern Australia','western Canada','southern Africa','布里斯班位于澳大利亚东部。'),q('brisbane',3,1,'Which activity is plausible in Brisbane?','taking a ferry along the Brisbane River','walking across the Sahara from the city center','visiting a Norwegian fjord by local tram','布里斯班有布里斯班河渡轮。'),q('brisbane',4,1,'Brisbane is a proper noun for a?','city in Queensland','type of salt','unit of length','Brisbane 是澳大利亚城市专名。')]});
D('briskness',{etymology:e('briskness 由形容词 brisk 加名词后缀 -ness 构成，表示动作、活动或寒冷天气所具有的轻快、活跃或清爽程度。','briskness'),contexts:[c('briskness.s1','秋日散步','The briskness of the autumn air made the walkers pick up their pace, but the clear sky kept the long route pleasant.','秋日空气的清爽让散步者加快了步伐，不过晴朗天空使长路线依然舒适。','The briskness of the autumn air / made the walkers pick up their pace / but the clear sky kept the long route pleasant.','briskness 是 made 的主语；make + 宾语 + 动词原形。','清凉而清爽的空气促使人加快步伐，体现天气义。')],mistakes:[m('The meeting’s briskness came from slow pauses after every sentence and long unrelated speeches.','The meeting’s sluggishness came from slow pauses after every sentence and long unrelated speeches.','长停顿和离题讲话显示会议拖沓，不是 briskness。')],quiz:[q('briskness',1,1,'The briskness of a walk refers to its?','quick, energetic pace','complete lack of movement','length in miles only','briskness 可指动作的轻快劲头。'),q('briskness',2,1,'Briskness in a cool morning may describe?','fresh, sharply cool air','hot air with no breeze','a silent written report','天气义 briskness 指清爽凉意。'),q('briskness',3,1,'A shop’s briskness of trade means?','business is active and moving quickly','the shop has no customers','every sale takes several weeks','商业活动 briskness 指生意兴旺活跃。'),q('briskness',4,1,'Which scene shows briskness?','Shoppers move quickly through a lively market.','A queue stands motionless for hours.','A store is closed for winter.','快速活跃的市场场景体现 briskness。')]});
D('Bristol',{etymology:e('Bristol 是英格兰西南部城市专名，其名源于古英语 Brycgstow，意为“桥边的地方”；现代城市位于埃文河畔。','Bristol'),contexts:[c('Bristol.s1','英国城市','On their trip to Bristol, the students crossed the Clifton Suspension Bridge and later toured the harbor where historic ships are displayed.','学生们到布里斯托尔旅行时走过克利夫顿吊桥，后来参观了陈列历史船只的港口。','On their trip to Bristol / the students crossed the Clifton Suspension Bridge / and later toured the harbor / where historic ships are displayed.','Bristol 是专名；where 引导修饰 harbor 的定语从句。','吊桥与历史港口是英格兰布里斯托尔的城市地标。')],mistakes:[m('Bristol is a city in south-west England, so the students flew there to visit the Great Barrier Reef.','Bristol is a city in south-west England, so the students flew there to visit its harbor and historic bridges.','大堡礁不在英国布里斯托尔；改成该市的港口和桥梁。')],quiz:[q('Bristol',1,1,'Bristol is a city in?','south-west England','northern Japan','central Argentina','布里斯托尔位于英格兰西南部。'),q('Bristol',2,1,'Which landmark is associated with Bristol?','the Clifton Suspension Bridge','the Sydney Opera House','the Great Pyramid of Giza','克利夫顿吊桥是布里斯托尔地标。'),q('Bristol',3,1,'A traveler visiting Bristol might see?','a historic harbor on the Avon','a coral reef in Queensland','a canal in the center of Mars','布里斯托尔是埃文河畔港口城市。'),q('Bristol',4,1,'Bristol is used as?','the proper name of an English city','a common noun for a type of bridge','an adjective meaning salty','Bristol 是城市专名。')]});
D('Britain',{etymology:e('Britain 经古法语和拉丁语 Britannia 进入英语，最终源头更早且有争议；现代用法既可指英格兰、苏格兰和威尔士组成的国家，也可指其所在的大岛。','Britain'),contexts:[c('Britain.s2','欧洲地理','Britain lies off the north-western coast of continental Europe, and the island contains England, Scotland, and Wales but not the island of Ireland.','不列颠位于欧洲大陆西北海岸外，这座大岛包含英格兰、苏格兰和威尔士，但不包括爱尔兰岛。','Britain lies off the north-western coast of continental Europe / and the island contains England, Scotland, and Wales / but not the island of Ireland.','Britain 作地理专名；but 对比岛屿包含与不包含的部分。','句子指英格兰、苏格兰和威尔士所在的大岛，符合 s2。')],mistakes:[m('Britain is the island containing England, Scotland, and Wales, so it includes the whole separate island of Ireland.','Britain is the island containing England, Scotland, and Wales, while the island of Ireland is separate.','大不列颠岛不包括爱尔兰岛；须区分相邻岛屿。')],quiz:[q('Britain',1,1,'Britain as a country comprises?','England, Scotland, and Wales','England and the whole island of Ireland','only the city of London','国家义 Britain 指英格兰、苏格兰和威尔士。'),q('Britain',2,2,'The island of Britain is geographically distinct from?','the island of Ireland','the island of Manhattan','the continent of Antarctica','大不列颠岛与爱尔兰岛是不同岛屿。'),q('Britain',3,1,'Which statement uses Britain for the island?','The island of Britain lies north-west of continental Europe.','Britain is a cooking tool in the kitchen.','Britain is a synonym for the entire world.','此处 Britain 指地理上的大岛。'),q('Britain',4,1,'Which region is part of Britain?','Scotland','the Republic of Ireland','Iceland','苏格兰属于不列颠。')]});
D('brittle',{etymology:e('brittle 来自古英语 brytel，和 break“破裂”同源，指硬而易裂，也可比喻脆弱、容易突然失效。','brittle'),contexts:[c('brittle.s2','停火谈判','Their cease-fire remained brittle: one disputed checkpoint could have ended the calm and restarted the fighting.','他们的停火局势仍很脆弱：一个有争议的检查站就可能结束平静、重启战斗。','Their cease-fire remained brittle / one disputed checkpoint could have ended the calm / and restarted the fighting.','brittle 作表语形容词；冒号后说明脆弱的原因。','停火可能因小事件突然破裂，符合抽象义 s2。')],mistakes:[m('The brittle glass bent easily without cracking when it fell onto the concrete.','The flexible plastic bent easily without cracking when it fell onto the concrete.','易碎玻璃通常会裂而不易弯曲；改用能弯曲的材料名。')],quiz:[q('brittle',1,1,'A brittle object is likely to?','crack or break rather than bend','stretch like elastic','remain soft like cloth','brittle 的物理义指硬而易裂。'),q('brittle',2,2,'A brittle political agreement may?','collapse suddenly under pressure','become stronger after every dispute','float on water','抽象义 brittle 表示脆弱、容易破裂。'),q('brittle',3,1,'Which material is most likely brittle?','thin dry glass','a rubber band','a woven cotton towel','玻璃较易碎裂，橡胶和布则能弯曲。'),q('brittle',4,2,'A brittle economy is one that?','can fail after a relatively small shock','cannot be affected by any event','has no financial activity','经济义表示容易受冲击而崩溃。')]});
D('broad-brimmed',{etymology:e('broad-brimmed 是 broad + brim + -ed 的复合形容词，字面指帽檐宽出的帽子；-ed 在此表示“具有……的”。','broad-brimmed'),contexts:[c('broad-brimmed.s1','户外防晒','The gardener wore a broad-brimmed hat while pruning the sunny side of the orchard, keeping the afternoon sun off her face and neck.','园丁修剪果园向阳的一侧时戴着宽檐帽，挡住午后阳光照在脸和脖子上。','The gardener wore a broad-brimmed hat / while pruning the sunny side of the orchard / keeping the afternoon sun off her face and neck.','broad-brimmed 修饰 hat；while pruning 省略与主句相同的主语。','宽帽檐可遮挡阳光，体现该形容词所指外形。')],mistakes:[m('He chose a broad-brimmed cap whose brim was only a narrow strip around the crown.','He chose a narrow-brimmed cap whose brim was only a narrow strip around the crown.','broad-brimmed 要求帽檐宽出帽冠；狭窄帽檐不符合。')],quiz:[q('broad-brimmed',1,1,'A broad-brimmed hat has?','a brim that extends widely around its crown','no brim at all','a narrow metal blade instead of fabric','该词描述帽檐宽阔。'),q('broad-brimmed',2,1,'Who may choose a broad-brimmed hat for shade?','a gardener working under strong sun','a diver in a sealed helmet underwater','a swimmer who needs a brimless cap','宽檐帽能为园丁遮阳。'),q('broad-brimmed',3,1,'Which description matches the hat?','Its projecting edge shades the wearer’s face.','Its crown is broad but its brim is absent.','It is made entirely of narrow wires.','帽檐伸出可遮住面部。'),q('broad-brimmed',4,1,'In this compound, brim refers to?','the projecting edge of a hat','the head inside the hat','the strap on a shoe','brim 是帽子伸出的边缘。')]});
D('broadleaf',{etymology:e('broadleaf 由 broad + leaf 构成，指具有宽阔扁平叶片的树木或植物，与针叶植物形成对照。','broadleaf'),contexts:[c('broadleaf.s1','林业生态','The forester mapped the broadleaf section of the woodland, where oak and beech trees lost their wide leaves each autumn.','护林员绘制了林地阔叶树区域的地图，那里橡树和山毛榉每到秋天都会落下宽大的叶片。','The forester mapped the broadleaf section of the woodland / where oak and beech trees lost their wide leaves each autumn.','broadleaf 作名词修饰 section，也可指阔叶树；where 引导地点从句。','橡树和山毛榉有宽扁叶片，符合阔叶植物义。')],mistakes:[m('A broadleaf pine keeps only thin needles and has no wide, flat leaves.','A coniferous pine keeps only thin needles and has no wide, flat leaves.','针叶松不属于宽叶植物；用 coniferous 描述其针叶特征。')],quiz:[q('broadleaf',1,1,'A broadleaf tree typically has?','wide, flat leaves rather than needles','only narrow needles','no leaves or leaf-like structures','broadleaf 指有宽扁叶片的植物。'),q('broadleaf',2,1,'Which is commonly a broadleaf tree?','oak','spruce','fir','橡树是常见阔叶树。'),q('broadleaf',3,1,'A broadleaf woodland differs from a conifer forest mainly in?','the shape of the trees’ leaves','the number of roads nearby','the color of the soil only','阔叶和针叶林主要以叶片形状区分。'),q('broadleaf',4,1,'The compound broadleaf literally points to?','a broad leaf','a broad river','a leafless branch','broad + leaf 即宽叶。')]});
D('broadly',{etymology:e('broadly 由 broad 加副词后缀 -ly 构成，可表示概括地、不细分地，也可指覆盖面广或广泛地。','broadly'),contexts:[c('broadly.s1','项目概述','Broadly speaking, the plan has two stages: repair the damaged bridge first, then replace the older road signs across the county.','概括地说，计划分两阶段：先修复受损桥梁，再更换全县较旧的道路标志。','Broadly speaking / the plan has two stages / repair the damaged bridge first / then replace the older road signs across the county.','固定短语 broadly speaking 作句子评注；冒号后列出概要。','说话者先给整体概要，体现“概括地”义。')],mistakes:[m('The report describes every tiny exception broadly, listing each case in exhaustive detail.','The report describes the issue broadly, leaving tiny exceptions for a separate appendix.','逐个列出所有细节是详尽分析，不是 broadly 的概括性表述。')],quiz:[q('broadly',1,1,'“Broadly speaking” signals that someone is?','giving a general summary','listing every minor detail','refusing to discuss the subject','该短语表示概括地说。'),q('broadly',2,2,'A rule applied broadly across a region reaches?','a wide range of places or people','one single desk only','no one outside a private room','广泛适用对应 broadly 的范围义。'),q('broadly',3,1,'Which sentence uses broadly to summarize?','Broadly, the proposal cuts costs but keeps services.','The word was broadly spelled with three silent letters.','The package broadly weighed exactly nothing.','这里 broadly 引出概括结论。'),q('broadly',4,2,'If residents broadly support a measure, support comes from?','many residents across the group','only one official','nobody at all','broadly support 表示支持范围广。')]});
D('broadside',{etymology:e('broadside 源自 broad + side，原指船的一侧及其舷炮齐射，也指印在一大张纸上的单页；“猛烈抨击”由齐射意象发展而来。','broadside'),contexts:[c('broadside.s1','媒体评论','After the council canceled the shelter project, the newspaper published a broadside accusing leaders of ignoring residents who needed housing.','市议会取消收容所项目后，报纸发表猛烈抨击，指责领导人无视需要住房的居民。','After the council canceled the shelter project / the newspaper published a broadside / accusing leaders of ignoring residents who needed housing.','broadside 作可数名词；accusing 分词短语说明抨击内容。','报纸公开而强烈地批评官员，符合攻击性评论义 s1。')],mistakes:[m('The columnist’s broadside praised the mayor warmly and made no criticism of the decision.','The columnist’s endorsement praised the mayor warmly and made no criticism of the decision.','热烈赞扬且没有批评不是 broadside；endorsement 更合适。')],quiz:[q('broadside',1,1,'A newspaper publishes a broadside against a policy. It has?','issued a strong public attack','printed a neutral bus timetable','praised the policy without reservation','比喻义 broadside 指猛烈抨击。'),q('broadside',2,2,'A ship fires a broadside when it?','uses the guns along one side together','sails backward without turning','drops its anchor on shore','船舶义是舷炮齐射。'),q('broadside',3,1,'Which could be called a broadside?','a sharply worded editorial condemning a decision','a brief note thanking a neighbor','a blank page in a notebook','措辞尖锐的社论属于攻击性评论。'),q('broadside',4,2,'A truck struck the barrier broadside, meaning it hit?','with its side facing the barrier','head-on with its front','from directly above','副词 broadside 可表示以侧面撞上。')]});
D('broadway',{etymology:e('Broadway 由 broad + way 构成；专名指纽约曼哈顿著名街道及其商业剧院区，普通名词义可指城镇中宽阔的主街。','broadway'),contexts:[c('broadway.s1','戏剧旅行','The actors rehearsed in a small studio for months before their musical opened on Broadway in a theater near Times Square.','演员们在小排练室里排练数月，之后他们的音乐剧才在时代广场附近的百老汇剧院首演。','The actors rehearsed in a small studio for months / before their musical opened on Broadway / in a theater near Times Square.','Broadway 作专名表示纽约百老汇剧院区；open on 表示在某地首演。','时代广场附近的商业剧院定位了专名义 s1。')],mistakes:[m('The musical opened on Broadway in a remote Australian village with no theater district.','The musical opened on Broadway in a New York theater near Times Square.','专名 Broadway 指纽约剧院区，不是澳大利亚偏远村落。')],quiz:[q('broadway',1,1,'A musical opening on Broadway is premiering in?','New York’s famous commercial theater district','a London underground station','a broad road in rural Australia','Broadway 专指纽约商业剧院区。'),q('broadway',2,2,'In another town, a broadway may simply be?','a wide main street','a narrow footpath','a private bedroom','普通义可指城镇宽阔主街。'),q('broadway',3,1,'Which phrase uses the New York proper name?','The cast hopes to take the show to Broadway.','The cast measured a broadway of two inches.','The cast brewed Broadway in a kettle.','把演出带到 Broadway 指纽约剧院区。'),q('broadway',4,1,'Times Square is closely associated with?','Broadway theater','Brisbane’s river port','a desert railway','时代广场与百老汇剧院区相邻。')]});
D('broccoli',{etymology:e('broccoli 借自意大利语 broccoli，为 broccolo“开花的嫩枝”复数；意大利词与 brocco“嫩芽、枝梢”有关。','broccoli'),contexts:[c('broccoli.s1','家庭烹饪','Before serving dinner, Jo steamed the broccoli until its thick stalks were tender but the small green flower buds still held their shape.','晚餐上桌前，乔把西兰花蒸到粗茎变软、绿色小花蕾仍保持形状。','Before serving dinner / Jo steamed the broccoli / until its thick stalks were tender / but the small green flower buds still held their shape.','broccoli 是不可数蔬菜名；until 引导蒸煮程度，but 表示转折。','可食的粗茎和花蕾说明此处指蔬菜本身 s1。')],mistakes:[m('The recipe asks for broccoli, so I bought a bag of beef instead of the green vegetable.','The recipe asks for broccoli, so I bought a head of the green vegetable.','牛肉不是西兰花；只需把食材替换为绿蔬菜。')],quiz:[q('broccoli',1,1,'The edible part of broccoli commonly includes?','a thick stalk and clusters of flower buds','a hard brown nut inside a shell','a red root with no stem','西兰花可食部分包括粗茎与花蕾。'),q('broccoli',2,2,'Broccoli is produced by which kind of plant?','a garden plant in the cabbage family','a fruit tree that grows lemons','a grass that produces wheat','broccoli 生长于十字花科园艺植物。'),q('broccoli',3,1,'Which cooking action is plausible for broccoli?','steaming its florets and stalk','brewing its seeds into coffee','sharpening its leaves into a knife','西兰花常以蒸、炒等方式烹饪。'),q('broccoli',4,1,'A shopper asks for broccoli at a produce stall. The seller should offer?','the green vegetable with clustered buds','a bottle of cooking vinegar','a bundle of pine needles','broccoli 是绿色蔬菜。')]});
D('bromine',{etymology:e('bromine 由法语 brome 加化学元素名后缀 -ine 构成；brome 源自希腊语 bromos“恶臭”，指这种元素的刺激性气味。','bromine'),contexts:[c('bromine.s1','化学实验室','Because bromine gives off a harmful reddish-brown vapor, the technician handled the sealed sample inside a functioning fume hood.','由于溴会释放有害的红棕色蒸气，技术员在正常运转的通风橱内处理密封样品。','Because bromine gives off a harmful reddish-brown vapor / the technician handled the sealed sample / inside a functioning fume hood.','bromine 作物质名；because 引出实验室防护的原因。','棕红色有害蒸气是溴元素的重要特征。')],mistakes:[m('The technician opened the bromine bottle in a crowded room because bromine is harmless and odorless.','The technician kept the bromine bottle sealed in a fume hood because bromine vapor is harmful and irritating.','溴蒸气有害且刺激，不能据称无害无味而在拥挤房间打开。')],quiz:[q('bromine',1,1,'Bromine is classified as a?','reddish-brown halogen element','colorless noble gas','metal used in coins','bromine 是红棕色卤素。'),q('bromine',2,1,'Why should bromine vapor be handled carefully?','it is harmful and irritating to breathe','it is ordinary fresh air','it instantly turns into drinking water','溴蒸气有害并会刺激呼吸道。'),q('bromine',3,1,'What is the chemical symbol for bromine?','Br','B','Bo','溴的元素符号是 Br。'),q('bromine',4,1,'A reddish-brown liquid halogen suggests?','bromine','helium','neon','溴在常温下呈红棕色并有刺激性气味。')]});
D('bronchitis',{etymology:e('bronchitis 由 bronch-（支气管）与医学名词后缀 -itis（炎症）构成，指支气管发炎的疾病。','bronchitis'),contexts:[c('bronchitis.s1','呼吸科就诊','After several days of a persistent cough and chest discomfort, the patient visited a clinic, where the doctor diagnosed bronchitis.','持续咳嗽并胸部不适数天后，患者前往诊所就诊，医生诊断为支气管炎。','After several days of a persistent cough and chest discomfort / the patient visited a clinic / where the doctor diagnosed bronchitis.','bronchitis 作疾病名；where 引导修饰 clinic 的定语从句。','持续咳嗽、支气管发炎的诊断符合疾病义。')],mistakes:[m('The doctor diagnosed bronchitis, but explained that the patient’s airways were not inflamed and there was no cough.','The doctor diagnosed bronchitis after finding inflamed airways and a persistent cough.','bronchitis 是气道炎症并常引发咳嗽；原句特征互相矛盾。')],quiz:[q('bronchitis',1,1,'Bronchitis is inflammation affecting the?','airways leading toward the lungs','outer layer of the skin','bones of the hand','bronchitis 指支气管等气道发炎。'),q('bronchitis',2,1,'A common symptom of bronchitis is a?','persistent cough','sudden change in eye color','broken ankle','咳嗽是支气管炎的常见症状。'),q('bronchitis',3,1,'The ending -itis in bronchitis signals?','inflammation','a surgical instrument','a measurement of distance','医学后缀 -itis 表示炎症。'),q('bronchitis',4,1,'Which patient might be evaluated for bronchitis?','someone coughing with inflamed airways','someone with a paper cut only','someone whose shoes are wet','气道炎症伴咳嗽可能需评估支气管炎。')]});
D('bronchus',{etymology:e('bronchus 源自希腊语 bronchos“气管、喉咙”，经拉丁语进入英语；复数为 bronchi，指气管分出的支气管之一。','bronchus'),contexts:[c('bronchus.s1','呼吸系统解剖','A bronchus carries air from the trachea toward one lung, where it branches into narrower tubes called bronchioles.','一条支气管把空气从气管送向一侧肺，在肺内再分成更细的细支气管。','A bronchus carries air from the trachea toward one lung / where it branches into narrower tubes / called bronchioles.','bronchus 是可数名词；where 引出肺内分支过程。','气管分支之一并通向一侧肺，对应单数解剖义。')],mistakes:[m('A bronchus carries food from the stomach to the heart during digestion.','An esophagus carries food from the throat toward the stomach during digestion.','bronchus 输送空气通往肺；运送食物的管道是 esophagus。')],quiz:[q('bronchus',1,1,'A bronchus is one of the tubes that carries?','air from the windpipe toward a lung','food from the stomach to the kidney','blood from the heart to the skin','bronchus 是连接气管和肺的气道。'),q('bronchus',2,1,'What is the plural of bronchus?','bronchi','bronchuseses','bronchii','bronchus 的常见复数是 bronchi。'),q('bronchus',3,1,'The trachea divides into?','two main bronchi','two stomachs','a pair of vocal cords','气管分叉为左右主支气管。'),q('bronchus',4,1,'A bronchoscope is used to examine?','the bronchus and airways','the outer surface of a shoe','the inside of a seed','bronchus 与呼吸道相关。')]});
D('brownish',{etymology:e('brownish 由 brown 加表示“稍带……色”的后缀 -ish 构成，意思是略带棕色或混有棕色。','brownish'),contexts:[c('brownish.s1','地质观察','The stream left a brownish stain on the white rock, suggesting that iron-rich soil had washed down from the hillside after rain.','溪水在白色岩石上留下淡棕色痕迹，说明雨后富含铁的土壤可能从山坡冲了下来。','The stream left a brownish stain on the white rock / suggesting / that iron-rich soil had washed down from the hillside after rain.','brownish 修饰 stain，表示色泽近棕但并非纯棕；suggesting 引出推测。','略呈棕色的沉积痕迹符合 -ish 表示稍带该色。')],mistakes:[m('The paper was brownish, a deep blue with no trace of brown.','The paper was bluish, a deep blue with no trace of brown.','纯深蓝而无棕色应称 bluish，不能称 brownish。')],quiz:[q('brownish',1,1,'A brownish liquid is?','somewhat brown in color','bright green throughout','completely transparent and colorless','brownish 表示略带棕色。'),q('brownish',2,1,'A brownish-gray coat has?','a mixture or shade of brown and gray','only vivid purple','no color at all','brownish-gray 混有棕色调。'),q('brownish',3,1,'Which thing could look brownish after rain?','muddy water carrying soil','fresh snow with no dirt','clear glass under clean light','土壤混入水中可使其呈淡棕色。'),q('brownish',4,1,'The suffix -ish in brownish usually means?','somewhat or tending toward','exactly and only','without any possibility of','-ish 表示稍微或带有某种倾向。')]});
D('brunt',{etymology:e('brunt 来自中古英语或古诺斯语相关形式，历史上指冲击或猛烈攻击；现代固定用于承受袭击、负担或冲击中最严重的部分。','brunt'),contexts:[c('brunt.s1','极端天气','The coastal villages bore the brunt of the storm, losing roofs and power while towns farther inland suffered only minor damage.','沿海村庄首当风暴冲击，屋顶被掀、电力中断，而更内陆的城镇只受轻微损坏。','The coastal villages bore the brunt of the storm / losing roofs and power / while towns farther inland suffered only minor damage.','固定搭配 bear the brunt of；while 对比沿海与内陆损失。','沿海承受风暴最严重部分，符合 brunt 义。')],mistakes:[m('The small island bore the brunt of the storm, but received none of the storm’s force or damage.','The small island escaped the brunt of the storm and received little damage.','bear the brunt 指承受最重冲击，不能同时完全未受其力。')],quiz:[q('brunt',1,1,'To bear the brunt of an attack is to?','suffer its strongest or worst part','avoid every effect of it','watch it from a safe distance','brunt 指攻击或冲击最猛烈部分。'),q('brunt',2,1,'Who bore the brunt of the repair burden?','the team that handled most of the urgent work','the visitor who did nothing','the team with no assigned task','承担主要负担就是 bear the brunt。'),q('brunt',3,1,'Complete the usual phrase: “The village bore the ___ of the flood.”','brunt','brunch','brim','习惯搭配为 bear the brunt of。'),q('brunt',4,1,'If workers bear the brunt of budget cuts, they?','are affected more severely than others','receive every extra benefit','are not affected at all','短语指承受削减带来的最大影响。')]});
D('brushstroke',{etymology:e('brushstroke 由 brush + stroke 组成，指画笔的一次落笔及其留下的笔触。','brushstroke'),contexts:[c('brushstroke.s1','绘画鉴赏','One confident brushstroke placed a dark branch across the pale sky, giving the landscape painting a stronger sense of movement.','一笔果断的笔触在浅色天空上画出深色树枝，让这幅风景画更有动感。','One confident brushstroke placed a dark branch across the pale sky / giving the landscape painting a stronger sense of movement.','brushstroke 作可数名词；giving 分词短语说明笔触带来的效果。','一次具体的画笔动作及其痕迹，符合 brushstroke 义。')],mistakes:[m('The artist created the line with a brushstroke by never touching a brush to the canvas.','The artist created the line with a pencil stroke by never touching a brush to the canvas.','没有用画笔落笔就不能称 brushstroke；pencil stroke 才符合。')],quiz:[q('brushstroke',1,1,'A brushstroke is?','one movement of a paintbrush and the mark it leaves','a hole cut through a canvas','a wooden frame around a picture','brushstroke 是画笔一次落笔及其笔迹。'),q('brushstroke',2,1,'A painter adds a broad brushstroke by?','moving the loaded brush across the surface','folding the canvas in half','measuring the frame with a ruler','画笔在画面上移动留下笔触。'),q('brushstroke',3,1,'Which word is closest to the visible mark of a brushstroke?','stroke','staple','staircase','笔触可以称为 stroke。'),q('brushstroke',4,1,'A critic calls a brushstroke delicate. The critic describes?','the painter’s applied mark','the room’s temperature','the canvas’s shipping cost','brushstroke 是绘画留下的笔迹。')]});
D('brusquely',{etymology:e('brusquely 是形容词 brusque 加副词 -ly 构成，描述说话或行事简短、生硬、唐突的方式。','brusquely'),contexts:[c('brusquely.s1','客服对话','When the caller asked for a refund, the clerk answered brusquely, “No,” and ended the call before hearing the explanation.','来电者申请退款时，店员生硬地答了句“不行”，没听解释就挂断电话。','When the caller asked for a refund / the clerk answered brusquely / and ended the call / before hearing the explanation.','brusquely 修饰 answered，说明说话态度；before hearing 表示未听说明前。','简短且不礼貌的回答体现 brusquely。')],mistakes:[m('The receptionist brusquely welcomed each visitor with a long, warm conversation and patient explanations.','The receptionist graciously welcomed each visitor with a long, warm conversation and patient explanations.','耐心热情且详尽的接待与 brusquely 的生硬简短相反。')],quiz:[q('brusquely',1,1,'Someone who answers brusquely speaks?','in a short, blunt, possibly rude way','at great length with careful warmth','in a whisper no one can hear','brusquely 指简短、生硬地回应。'),q('brusquely',2,1,'Which reply is most likely brusque?','“No. Leave.”','“I’d be glad to explain the options.”','“Thank you for asking; let me check.”','冷硬命令式回答体现 brusque。'),q('brusquely',3,1,'Choose a natural sentence.','He brusquely refused to discuss the matter.','He brusquely smiled with endless patient detail.','He answered brusquelyly.','brusquely 修饰 refused，拼写不再加 -ly。'),q('brusquely',4,1,'If a manager speaks brusquely, employees may feel?','dismissed by the blunt tone','welcomed by a warm detailed greeting','confused because no one spoke','生硬语气可能令人觉得受怠慢。')]});
D('bubbly',{etymology:e('bubbly 由 bubble 加形容词后缀 -y 构成，指充满气泡，也可非正式地形容活泼开朗的人或起泡酒。','bubbly'),contexts:[c('bubbly.s1','饮料观察','The mineral water turned bubbly when the waiter poured it into a glass, and tiny streams of carbon dioxide rose to the surface.','侍者把矿泉水倒进杯里后，水开始冒泡，细小的二氧化碳气泡不断升到表面。','The mineral water turned bubbly / when the waiter poured it into a glass / and tiny streams of carbon dioxide rose to the surface.','bubbly 作表语形容词；when 引导时间状语从句。','水中气体形成可见气泡，符合物理义 s1。')],mistakes:[m('The bubbly soda had no bubbles, no dissolved gas, and a completely flat surface.','The flat soda had no bubbles, no dissolved gas, and a completely still surface.','没有气泡且已走气的饮料是 flat，不是 bubbly。')],quiz:[q('bubbly',1,1,'A bubbly drink contains?','many visible bubbles','no gas or fizz at all','solid ice only','bubbly 可指充满气泡。'),q('bubbly',2,2,'A bubbly person is usually?','cheerful and lively','silent and persistently gloomy','made of liquid','比喻义 bubbly 描写活泼开朗。'),q('bubbly',3,1,'Which drink might be called bubbly?','sparkling water with rising fizz','still water that has gone flat','a cup of thick dry flour','起泡水有气泡，符合 bubbly。'),q('bubbly',4,2,'At a celebration, “some bubbly” can mean?','champagne or another sparkling wine','a plate of plain rice','a glass of motor oil','口语中 bubbly 可指起泡酒。')]});
D('buckskin',{etymology:e('buckskin 由 buck（雄鹿）+ skin 构成，原指鹿皮及其制成的柔软皮革；也指具有黄褐色被毛、黑色鬃尾的马。','buckskin'),contexts:[c('buckskin.s1','传统服饰','The craftworker stitched soft buckskin into gloves for the winter fair, choosing a supple hide that would bend easily around the fingers.','手艺人为冬季集市缝制柔软鹿皮手套，挑选了能在手指周围轻易弯曲的皮革。','The craftworker stitched soft buckskin into gloves for the winter fair / choosing a supple hide / that would bend easily around the fingers.','buckskin 作不可数材料名；that 引导说明皮革特性的定语从句。','柔软的鹿皮材料符合 s1。')],mistakes:[m('The gloves were made of buckskin, a rigid sheet of glass that could not bend around a hand.','The gloves were made of buckskin, a soft leather that could bend around a hand.','鹿皮革柔软可弯曲，不是玻璃板。')],quiz:[q('buckskin',1,1,'Buckskin gloves are traditionally made from?','soft deer leather','woven copper wire','glass fibers','buckskin 是鹿皮制成的皮革。'),q('buckskin',2,2,'A buckskin horse has which coat pattern?','yellowish coat with a black mane and tail','white coat with a green mane','solid black coat with no mane','buckskin 也指黄褐身、黑鬃尾的马。'),q('buckskin',3,1,'Which item could be made from buckskin?','supple leather gloves','a ceramic teapot','a steel bridge cable','鹿皮可制作柔软衣物或手套。'),q('buckskin',4,1,'The word originally connects buck with?','the hide of a deer','a type of boat engine','a unit of time','buckskin 字面指鹿皮。')]});
D('budge',{etymology:e('budge 源自古法语 bouger“移动”，与晚期拉丁语 bullicare“沸腾、涌动”相关；现代可指稍微移动，也可指让步。','budge'),contexts:[c('budge.s3','谈判立场','Even after the supplier offered a discount, the buyer would not budge on the safety requirement, insisting that every part meet the same standard.','即使供应商提出折扣，买家也不肯在安全要求上让步，坚持每个零件都达到同一标准。','Even after the supplier offered a discount / the buyer would not budge on the safety requirement / insisting that every part meet the same standard.','budge 作不及物动词，常接 on 表示不改变的议题；would not 表示拒绝。','买家坚持安全标准、不改变立场，符合 s3。')],mistakes:[m('After hearing no new evidence, the judge budged from the original ruling and changed nothing at all.','After hearing no new evidence, the judge did not budge from the original ruling and changed nothing at all.','改变立场与“完全没改”矛盾；此处应使用否定 did not budge。')],quiz:[q('budge',1,1,'A stuck cabinet that will not budge?','will not move even a little','opens itself smoothly','turns into a smaller cabinet','budge 的物理义是稍微移动。'),q('budge',2,2,'To budge a heavy crate is to?','push it a short distance','paint it a new color','measure it without touching','及物 budge 可指推动物体一点。'),q('budge',3,3,'A negotiator who will not budge on price?','refuses to change their position','moves the table across the room','forgets the price immediately','budge on 表示在某议题上让步。'),q('budge',4,3,'Which sentence uses budge figuratively?','The council would not budge on the deadline.','The wheel budged one inch when pushed.','She budged the box across the floor.','坚持期限是比喻义“拒绝让步”。')]});
D('buggy',{etymology:e('buggy 由 bug 加形容词后缀 -y 表示“有虫的、故障多的”；作名词时指轻便马车，词源细节与另一形容词义并非同一构词解释。','buggy'),contexts:[c('buggy.s2','软件测试','The update looked stable in the demo, but the release proved buggy: users could not save files and the search screen froze repeatedly.','更新在演示中看似稳定，但正式版故障很多：用户无法保存文件，搜索界面也反复卡死。','The update looked stable in the demo / but the release proved buggy / users could not save files / and the search screen froze repeatedly.','buggy 作表语形容词；冒号后给出软件故障实例。','无法保存和反复卡死说明软件缺陷多，符合 s2。')],mistakes:[m('The buggy program ran without a single fault, saved every file, and never froze.','The reliable program ran without a single fault, saved every file, and never froze.','没有任何故障的软件不应称 buggy。')],quiz:[q('buggy',1,2,'A buggy app is one that?','has many faults or software defects','never produces any error','is pulled by a horse','软件义 buggy 表示故障多。'),q('buggy',2,1,'A horse-drawn buggy is?','a light carriage','a software update','a type of insect','名词 buggy 可指轻便马车。'),q('buggy',3,1,'Which person might use a buggy for a baby?','a parent pushing a child in a stroller','a programmer compiling a program','a farmer sowing wheat','英式 buggy 可指婴儿车。'),q('buggy',4,2,'The test team calls the release buggy after?','finding frequent crashes and lost files','confirming every feature works perfectly','printing a clean instruction manual','反复崩溃和文件丢失体现软件缺陷。')]});
D('built-in',{etymology:e('built-in 由 built + in 构成，最初描述嵌入整体结构的部件；作形容词也指天生具有、固有的特征。','built-in'),contexts:[c('built-in.s2','电子设备','The camera has a built-in microphone, so the reporter can record clear audio without plugging in an extra accessory.','相机内置麦克风，因此记者无需另接配件就能录下清晰音频。','The camera has a built-in microphone / so the reporter can record clear audio / without plugging in an extra accessory.','built-in 作复合形容词修饰 microphone；without 后接动名词。','麦克风集成在设备内部，符合内置部件义 s2。')],mistakes:[m('The camera’s built-in microphone is a separate accessory that must be purchased and plugged in each time.','The camera’s external microphone is a separate accessory that must be purchased and plugged in each time.','需要另购并外接的配件不是 built-in；external 更准确。')],quiz:[q('built-in',1,2,'A built-in speaker is?','installed as a permanent part of a device','rented separately for one day','stored in another building','built-in 表示装在设备内部。'),q('built-in',2,1,'A built-in shelf is usually?','fitted into the wall or structure','a loose book carried in a bag','a temporary sign outside','内嵌式搁架成为建筑结构的一部分。'),q('built-in',3,1,'A built-in advantage is?','an inherent feature someone already has','a tool borrowed from a neighbor','a benefit that must be imported','引申义 built-in 可表示固有的。'),q('built-in',4,2,'Which item is built-in to a laptop?','its integrated keyboard','a detachable umbrella bought separately','a chair in another room','集成在笔记本中的键盘可称 built-in。')]});
D('bulge',{etymology:e('bulge 经中古法语或中古英语形式进入英语，指圆凸、鼓起；可作名词表示凸起部分，也可作动词表示鼓胀或使鼓出。','bulge'),contexts:[c('bulge.s2','行李检查','The zipper would not close because the overpacked suitcase began to bulge at the sides, stretching the fabric around its seams.','行李箱塞得太满，两侧开始鼓起，拉链无法合上，接缝周围的布料也绷紧了。','The zipper would not close / because the overpacked suitcase began to bulge at the sides / stretching the fabric around its seams.','bulge 作不及物动词，指箱体向外鼓出；because 引出拉链合不上的原因。','箱体侧面隆起，符合动词义 s2。')],mistakes:[m('The tightly packed suitcase bulged inward, leaving its outer sides perfectly flat and unstrained.','The tightly packed suitcase bulged outward, stretching its outer sides.','bulge 指向外凸起，不是向内凹陷。')],quiz:[q('bulge',1,2,'A suitcase that begins to bulge is?','swelling outward under pressure','shrinking into a smaller shape','becoming completely empty','动词 bulge 指向外鼓起。'),q('bulge',2,1,'A bulge under a carpet is?','a raised rounded area','a hole cut through the floor','a clean flat surface','名词 bulge 可指表面凸起。'),q('bulge',3,3,'To bulge a pocket is to?','make it stick out by filling it','remove everything from it','fold it into a flat seam','及物动词义表示使之鼓胀突出。'),q('bulge',4,2,'Which observation describes a bulging wall?','a rounded section sticks outward','the wall has no change in shape','the wall becomes shorter in height','凸出的圆形部分叫 bulge。')]});
D('bulimia',{etymology:e('bulimia 经拉丁化医学用语源自希腊语 boulimia“极度饥饿”；现代专指一种进食障碍，历史词源并不等同于完整临床定义。','bulimia'),contexts:[c('bulimia.s1','医疗支持','After noticing a repeated pattern of binge eating and distress, the student spoke with a clinician, who explained that bulimia is a serious condition that deserves professional care.','注意到反复暴食和痛苦后，学生向临床人员求助；对方解释说，贪食症是一种需要专业照护的严重疾病。','After noticing a repeated pattern of binge eating and distress / the student spoke with a clinician / who explained that bulimia is a serious condition / that deserves professional care.','bulimia 为疾病名词；who 与 that 从句分别修饰 clinician 和 condition。','反复暴食、痛苦并寻求专业照护，符合进食障碍语境。')],mistakes:[m('Bulimia is simply enjoying a large meal once, so anyone with it never experiences a repeated eating pattern or distress.','Bulimia is a serious eating disorder involving recurrent binge-eating patterns and related distress, so professional assessment can help.','把严重的反复进食障碍简化成偶尔吃得多，会忽视持续模式与心理痛苦。')],quiz:[q('bulimia',1,1,'Bulimia is classified as a?','serious eating disorder','type of stomach flu','normal response to one large meal','bulimia 是一种进食障碍，并非偶尔吃多一餐。'),q('bulimia',2,1,'Which response is appropriate when someone is distressed by repeated eating patterns?','encourage them to seek qualified professional support','shame them about food choices','assume they can resolve every concern alone','这类严重状况应得到专业支持。'),q('bulimia',3,1,'Bulimia involves a pattern that is?','recurrent and clinically significant','limited to one ordinary meal','a cooking method','疾病义强调重复发生的进食模式。'),q('bulimia',4,1,'Which statement is most accurate?','Bulimia is a serious condition, not a casual synonym for appetite.','Bulimia means a person enjoys vegetables.','Bulimia is a harmless name for hunger after exercise.','bulimia 指特定严重疾病，不能泛指普通食欲。')]});
D('bulky',{etymology:e('bulky 由 bulk（体积、块状物）加形容词后缀 -y 构成，形容占空间大、笨重或难搬运。','bulky'),contexts:[c('bulky.s1','搬家运输','The bulky wardrobe would not fit through the stairwell, so the movers removed its doors and carried the frame through at an angle.','这只大而笨重的衣柜无法通过楼梯间，搬运工只好拆下柜门并斜着把框架抬过去。','The bulky wardrobe would not fit through the stairwell / so the movers removed its doors / and carried the frame through at an angle.','bulky 修饰 wardrobe；so 引出体积带来的搬运结果。','占空间且难以通过楼梯的家具体现 bulky。')],mistakes:[m('The bulky package was tiny, flat, and easy to slip into a shirt pocket.','The compact package was tiny, flat, and easy to slip into a shirt pocket.','体积小且易装入口袋不符合 bulky。')],quiz:[q('bulky',1,1,'A bulky object usually?','takes up a lot of space and is awkward to handle','fits easily in a tiny pocket','weighs exactly nothing and occupies no space','bulky 指占空间且不便搬动。'),q('bulky',2,1,'Which item is most likely bulky?','a large wardrobe being moved upstairs','a single postage stamp','a thin paper clip','大型衣柜占空间，搬运不便。'),q('bulky',3,1,'A bulky winter coat is difficult to?','pack into a small bag','wear over other clothing','keep warm in cold weather','厚重外套不易塞进小包。'),q('bulky',4,1,'The word bulky primarily describes?','size and handling difficulty','a bright color','a sharp flavor','bulky 强调体积和搬运难度。')]});
D('bulldoze',{etymology:e('bulldoze 由 bull + dose 构成，19世纪美国英语原指强制威吓，后因推土机的 bulldozer 而发展出“用推土机铲平”，再引申为强行压过反对意见。','bulldoze'),contexts:[c('bulldoze.s2','社区规划','The developer tried to bulldoze residents into accepting the plan, but the neighborhood group insisted on a public hearing before any vote.','开发商试图强迫居民接受方案，但社区组织坚持先举行公开听证，再进行表决。','The developer tried to bulldoze residents into accepting the plan / but the neighborhood group insisted on a public hearing / before any vote.','bulldoze sb into doing sth 表示施压迫使某人做某事。','开发商以压力迫使居民同意，符合比喻义 s2。')],mistakes:[m('The chair bulldozed the committee into agreement by patiently listening to every objection and allowing a free vote.','The chair persuaded the committee through discussion by patiently hearing every objection and allowing a free vote.','倾听并自由表决不是强压；bulldoze 暗含不顾反对施压。')],quiz:[q('bulldoze',1,2,'To bulldoze a building is to?','knock it down with heavy machinery','paint its walls','move its tenants to a new office','字面义是用推土机拆平建筑。'),q('bulldoze',2,2,'To bulldoze someone into agreeing is to?','pressure them to agree against resistance','invite them to discuss freely','wait until they make their own choice','比喻义指强迫他人接受。'),q('bulldoze',3,1,'Which sentence uses bulldoze literally?','Workers bulldozed the unsafe shed before rebuilding.','The manager bulldozed the vote by threatening critics.','The truck bulldozed the calendar into next week.','拆除棚屋是推土机的字面用法。'),q('bulldoze',4,2,'A team that bulldozes objections is likely to?','ignore opposition and force its decision through','carefully revise a plan after feedback','postpone action for open discussion','无视异议强行推进是其比喻义。')]});
D('bulldozer',{etymology:e('bulldozer 由 bulldoze 加施事者后缀 -er 构成，指带有前推铲板、用于推土或平整地面的履带式工程车辆。','bulldozer'),contexts:[c('bulldozer.s1','道路施工','The bulldozer pushed soil away from the new roadbed while a surveyor checked the slope and marked where the drainage ditch should run.','推土机把新路基上的泥土推开，测量员则检查坡度并标出排水沟走向。','The bulldozer pushed soil away from the new roadbed / while a surveyor checked the slope / and marked where the drainage ditch should run.','bulldozer 作主语；while 引出同时进行的测量工作。','用前铲推动土方是推土机的典型用途。')],mistakes:[m('The bulldozer lifted passengers between floors using an enclosed cabin and elevator cables.','The elevator lifted passengers between floors using an enclosed cabin and cables.','乘客升降设备是电梯；推土机用于施工推土。')],quiz:[q('bulldozer',1,1,'A bulldozer is a tracked machine with?','a large blade for pushing earth','a cabin designed only for lifting passengers','a long fishing net','推土机前部装有推土铲板。'),q('bulldozer',2,1,'Which job suits a bulldozer?','clearing soil from a construction site','printing office documents','weaving cloth','推土机可清理施工现场土方。'),q('bulldozer',3,1,'A bulldozer is distinguished from a road car by its?','heavy tracks and earth-moving blade','sails and mast','glass shelves','履带与推土铲用于工程作业。'),q('bulldozer',4,1,'What does the machine mainly push?','soil or debris','letters into an envelope','water through a straw','bulldozer 的主要工作是推土或杂物。')]});
D('bullrush',{etymology:e('bullrush 是 bull + rush 的英语植物名复合词，指生长在水边的高大芦苇状植物；该俗名可与 cattail 等名称交叠。','bullrush'),contexts:[c('bullrush.s1','湿地植物','Tall bullrushes grew along the marsh channel, their sturdy stems sheltering small birds that nested close to the water.','沼泽水道边长着高高的香蒲状水生植物，结实的茎为贴近水边筑巢的小鸟提供了遮蔽。','Tall bullrushes grew along the marsh channel / their sturdy stems sheltering small birds / that nested close to the water.','bullrushes 为复数名词；that 引导修饰 birds 的定语从句。','水边高秆植物及其湿地生境符合 bullrush 义。')],mistakes:[m('The bullrush grew on a dry mountaintop far from water and had no tall stem.','The bullrush grew beside the marsh and developed a tall waterside stem.','bullrush 是高大的水边植物；干燥山顶且无高茎与其生境特征不符。')],quiz:[q('bullrush',1,1,'A bullrush is typically found?','growing tall beside water','buried inside dry desert rock','floating in the upper atmosphere','bullrush 常长在湿地或水边。'),q('bullrush',2,1,'Which habitat suits bullrushes?','a marsh edge','a dry office drawer','a snowy rooftop','水边湿地适合这种植物生长。'),q('bullrush',3,1,'A bird might use a patch of bullrushes for?','shelter near a wetland','a source of metal tools','a place to store books','高秆植物可在湿地为小鸟遮蔽。'),q('bullrush',4,1,'The word bullrush names a?','tall waterside plant','type of construction vehicle','unit of rainfall','bullrush 是水边植物名。')]});
D('bulwark',{etymology:e('bulwark 源自中古低地德语 bolwerk 一类词，原指堡垒或防御工事；现也比喻提供有力保护的原则、制度或人。','bulwark'),contexts:[c('bulwark.s1','海岸防御','The old stone bulwark shielded the harbor entrance from direct attack, and soldiers could watch the channel from its raised platform.','这座古老石制防御墙保护港口入口免遭正面袭击，士兵能从高台上观察航道。','The old stone bulwark shielded the harbor entrance from direct attack / and soldiers could watch the channel / from its raised platform.','bulwark 作主语名词；shield from 表示保护免受某种威胁。','石墙和高台承担防御功能，符合名词义。')],mistakes:[m('The low open gate served as a bulwark, leaving the harbor completely exposed to every direct attack.','The fortified stone wall served as a bulwark, protecting the harbor from direct attack.','完全暴露的入口不能提供防御；bulwark 应起保护作用。')],quiz:[q('bulwark',1,1,'A bulwark in a harbor is a?','defensive wall or barrier','narrow dining spoon','kind of sailing timetable','bulwark 可指防御墙。'),q('bulwark',2,1,'A strong independent court may be called a bulwark of?','civil liberties','poor eyesight','summer rainfall','比喻义 bulwark 指有力保护或支柱。'),q('bulwark',3,1,'Which item acts as a bulwark against flooding?','a reinforced sea wall','a paper flag','an open drain facing the sea','海堤可以抵御洪水。'),q('bulwark',4,1,'The metaphorical phrase “a bulwark of democracy” means?','a safeguard that strongly protects it','a small decoration with no effect','a sign that democracy has ended','比喻指维护民主的重要保障。')]});
D('bumblebee',{etymology:e('bumblebee 由 bumble（嗡嗡作声）+ bee 构成，是英语中对体型较大、毛茸茸且飞行嗡鸣的蜂类的称呼。','bumblebee'),contexts:[c('bumblebee.s1','花园授粉','A bumblebee moved from flower to flower in the community garden, carrying pollen between the blossoms as volunteers watered the vegetable beds.','一只大黄蜂在社区花园里穿梭于花朵之间，把花粉带到不同花丛，志愿者则在给菜畦浇水。','A bumblebee moved from flower to flower in the community garden / carrying pollen between the blossoms / as volunteers watered the vegetable beds.','bumblebee 作主语名词；carrying 分词结构说明飞行中的授粉活动。','毛茸茸蜂类在花间采粉，符合 bumblebee。')],mistakes:[m('The bumblebee pollinated the flowers without wings, a stinger, or any ability to fly.','The bumblebee pollinated the flowers while flying between them and carrying pollen.','大黄蜂靠飞行到访花朵；句中“无翅且不能飞”与行为矛盾。')],quiz:[q('bumblebee',1,1,'A bumblebee is a?','large, hairy bee with a buzzing flight','small fish that lives in ponds','wingless beetle that burrows underground','bumblebee 是体型较大、飞行嗡鸣的蜂。'),q('bumblebee',2,1,'Why might a gardener welcome bumblebees?','they carry pollen between flowers','they remove every plant from the garden','they turn soil into glass','大黄蜂访花时能帮助传授花粉。'),q('bumblebee',3,1,'Which sound is associated with a bumblebee?','a deep buzz in flight','a horse’s neigh','a metal bell ringing underwater','其飞行时常发出低沉嗡嗡声。'),q('bumblebee',4,1,'A bumblebee is most likely seen?','visiting blossoms in a garden','swimming below a coral reef','working inside a computer','大黄蜂常在花园访花。')]});
D('bungalow',{etymology:e('bungalow 由印地语 bangla“孟加拉风格的”经英语借入，原指孟加拉式低矮房屋，后来泛指通常只有一层的独立住宅。','bungalow'),contexts:[c('bungalow.s1','住房介绍','The retired couple chose a bungalow with a ramp and a garden, so they could reach every room without climbing stairs.','这对退休夫妇选了一栋带坡道和花园的平房，这样不用爬楼梯就能到达每个房间。','The retired couple chose a bungalow with a ramp and a garden / so they could reach every room / without climbing stairs.','bungalow 作可数名词；without climbing 表示无需爬楼梯。','一层住宅使住户无需上下楼梯，符合词条义。')],mistakes:[m('The family rented a bungalow with five upstairs floors and a lift serving each level.','The family rented a multistory house with five upstairs floors and a lift serving each level.','五层楼住宅不符合 bungalow 通常单层的特点。')],quiz:[q('bungalow',1,1,'A bungalow is usually?','a house built on one level','a tower with dozens of floors','a tent with no walls','bungalow 通常指平房或单层住宅。'),q('bungalow',2,1,'A buyer who wants to avoid stairs may prefer a?','bungalow','high-rise apartment','three-story townhouse','单层房屋不用上下楼梯。'),q('bungalow',3,1,'Which listing most likely describes a bungalow?','single-story home with a small garden','office tower with thirty floors','underground station platform','独立单层住宅符合 bungalow。'),q('bungalow',4,1,'The historical name bungalow originally referred to a style from?','Bengal','Brazil','Belgium','bungalow 来源于印地语 bangla，与孟加拉风格相关。')]});
D('bunk',{etymology:e('bunk 作为名词指狭窄卧铺，其词源不确定；作动词可指睡在铺位上，也见于非正式短语 bunk off（旷课或擅自离开）。','bunk'),contexts:[c('bunk.s2','学生生活','After finishing the late shift, Kai bunked in the spare room for a few hours before returning to the station for the morning train.','加完晚班后，凯在备用房间的铺位上睡了几个小时，之后回车站赶早班火车。','After finishing the late shift / Kai bunked in the spare room for a few hours / before returning to the station for the morning train.','bunked 作不及物动词，表示睡在简易铺位上；before 引出随后发生的动作。','在房间铺位上短暂睡觉，符合动词义 s2。')],mistakes:[m('The sailors bunked comfortably in the narrow berths, but the report says none of them slept there.','The sailors stored their gear in the narrow berths, but the report says none of them slept there.','若并未在铺位睡觉，就不应使用 bunked 表示睡在铺位上。')],quiz:[q('bunk',1,1,'A bunk on a ship is usually?','a narrow bed or berth','a large dining table','a type of steering wheel','名词 bunk 指狭窄床铺。'),q('bunk',2,2,'To bunk in a cabin means to?','sleep in one of its berths','paint its walls','leave a ship permanently','动词 bunk 可指睡在卧铺上。'),q('bunk',3,2,'If a pupil bunks off school, the pupil?','skips class or leaves without permission','wins a school prize','takes a scheduled exam','bunk off 是逃课或擅自离开的非正式表达。'),q('bunk',4,1,'A bunk bed has?','two narrow beds, often stacked','one oversized dining bench','four separate kitchens','上下铺常称 bunk beds。')]});
D('buoyancy',{etymology:e('buoyancy 由 buoyant 加名词后缀 -cy 构成，指物体在液体或气体中的浮力/漂浮能力，也可指乐观振作的精神状态。','buoyancy'),contexts:[c('buoyancy.s1','水上安全','The life jacket’s buoyancy kept the exhausted swimmer’s head above the water until the rescue boat reached the shore.','救生衣的浮力让筋疲力尽的游泳者头部保持在水面上，直到救援船抵达岸边。','The life jacket’s buoyancy kept the exhausted swimmer’s head above the water / until the rescue boat reached the shore.','buoyancy 作不可数名词；keep + 宾语 + 形容词短语说明作用。','向上的浮力使人漂浮并保持头部在水面，符合 s1。')],mistakes:[m('The metal weight increased the swimmer’s buoyancy and pulled the swimmer farther below the surface.','The metal weight reduced the swimmer’s buoyancy and pulled the swimmer farther below the surface.','向下的重物减弱漂浮能力，不会增加浮力。')],quiz:[q('buoyancy',1,1,'Buoyancy is the force that?','pushes an object upward in a fluid','pulls every object toward the ocean floor','turns fresh water into salt','浮力是在液体或气体中向上的作用力。'),q('buoyancy',2,2,'A person’s buoyancy can refer metaphorically to?','cheerful resilience after setbacks','the number of stairs at home','a dislike of swimming','比喻义 buoyancy 指振作乐观的精神。'),q('buoyancy',3,1,'Why can a life jacket help someone float?','it increases upward support in water','it removes all water from a lake','it makes the person heavier than the boat','救生衣提供帮助漂浮的浮力。'),q('buoyancy',4,1,'Which object shows buoyancy in action?','a cork floating on water','a stone resting at the bottom','a paper sheet burning in air','软木塞浮水体现浮力。')]});
D('buoyant',{etymology:e('buoyant 经法语 bouyant 进入英语，与 buoy“浮标”相关，表示有浮力、能漂浮；引申为情绪乐观或快速回升。','buoyant'),contexts:[c('buoyant.s2','市场情绪','Although sales fell during the winter, the company’s buoyant outlook returned after customers responded well to the spring launch.','尽管冬季销量下滑，顾客对春季新品反响良好后，公司又恢复了乐观的前景判断。','Although sales fell during the winter / the company’s buoyant outlook returned / after customers responded well to the spring launch.','buoyant 修饰 outlook；although 表示让步，after 引出转好原因。','前景重新乐观，体现精神或趋势回升义 s2。')],mistakes:[m('The buoyant outlook meant the managers expected certain failure and refused to consider improvement.','The pessimistic outlook meant the managers expected failure and refused to consider improvement.','预期失败且拒绝改进不属于乐观振奋的 buoyant outlook。')],quiz:[q('buoyant',1,1,'A buoyant object in water?','stays at or rises toward the surface','sinks immediately in every liquid','dissolves as soon as it touches water','物理义 buoyant 指能漂浮。'),q('buoyant',2,2,'A buoyant mood is?','cheerful and hopeful','persistently hopeless','physically heavy','比喻义 buoyant 指乐观振奋。'),q('buoyant',3,2,'A buoyant recovery in sales means sales?','are rising or recovering quickly','have disappeared permanently','are being measured in liters','buoyant 可形容迅速回升的趋势。'),q('buoyant',4,1,'A cork is buoyant because it?','floats on water','is denser than a lead weight','cannot enter a liquid','软木塞具有浮力，能漂在水面。')]});
D('bur',{etymology:e('bur（亦作 burr）指带钩刺、会粘在衣物或动物皮毛上的粗糙种荚；词的更早词源不确定，不据拼写臆造词根。','bur'),contexts:[c('bur.s1','野外观察','After the dog ran through the meadow, several burrs clung to its coat and had to be picked out carefully before brushing.','狗跑过草地后，几颗带刺种荚粘在它的毛上，梳毛前必须仔细取下来。','After the dog ran through the meadow / several burrs clung to its coat / and had to be picked out carefully before brushing.','bur 的复数常写 burrs；cling to 表示粘附在表面。','会钩粘在毛发上的种荚符合植物名义。')],mistakes:[m('The smooth seed pod with no hooks slid off the dog’s coat and is a typical bur.','The hooked seed pod clung to the dog’s coat and is a typical bur.','典型 bur 有能钩住衣物或皮毛的刺，不是光滑不粘的种荚。')],quiz:[q('bur',1,1,'A bur from a plant is usually?','a rough hooked seed pod that clings to things','a smooth stone from a river','a bird nest made of feathers','bur 指会粘附的带刺种荚。'),q('bur',2,1,'Why might a burr stick to a dog’s coat?','its hooks catch on fur','it melts into the animal’s skin','it is made of glue from a bottle','钩刺会勾住毛发。'),q('bur',3,1,'Which plant part could be a bur?','a spiny seed head carried on clothing','a flower petal with no seeds','a flat leaf that falls into water','带刺种头属于 bur。'),q('bur',4,1,'A hiker finds burs on a sock after walking through?','a field of plants with hooked seed pods','a polished indoor floor','a paved road with no vegetation','带刺种荚可粘在袜子上。')]});
D('bureaucracy',{etymology:e('bureaucracy 经法语 bureaucratie 构成：bureau“办公桌、办公室”加希腊语 -kratia“统治、管理”；既可指繁琐官僚制度，也可指其官员群体。','bureaucracy'),contexts:[c('bureaucracy.s1','行政审批','The small grant was delayed by bureaucracy: three departments demanded separate forms, even though each form asked for the same information.','这笔小额拨款被繁琐的官僚程序拖延了：三个部门分别要求填写表格，尽管每份表格都问同样的信息。','The small grant was delayed by bureaucracy / three departments demanded separate forms / even though each form asked for the same information.','bureaucracy 作不可数名词；冒号后解释造成延误的程序负担。','重复表格和部门流程体现繁复官僚制度义 s1。')],mistakes:[m('The application moved instantly through bureaucracy because no department required forms or approvals.','The application moved instantly through the streamlined process because no department required forms or approvals.','无表格无审批、即时办结不是繁琐的 bureaucracy。')],quiz:[q('bureaucracy',1,1,'A complaint about bureaucracy usually concerns?','complicated rules and slow official procedures','a lack of any public organization','a celebration at a private home','bureaucracy 常含规则繁杂、效率低的意思。'),q('bureaucracy',2,2,'“The bureaucracy issued new guidance” can refer to?','the officials who administer an organization','a single citizen with no official role','the building’s heating system','bureaucracy 也可指官僚或行政官员群体。'),q('bureaucracy',3,1,'Which situation illustrates bureaucracy?','several offices require duplicate paperwork for one permit','one clear form is approved in minutes','a neighbor lends a book','重复手续会造成繁琐官僚程序。'),q('bureaucracy',4,1,'The word combines bureau with an element meaning?','rule or administration','water','sound','-cracy 表示统治或管理。')]});
D('bureaucratic',{etymology:e('bureaucratic 由 bureaucracy/bureaucrat 加形容词后缀 -ic 构成，表示与行政官僚体系有关，或程序过多、拘泥规则。','bureaucratic'),contexts:[c('bureaucratic.s2','工作流程','The approval process had become bureaucratic: staff copied the same data onto five forms before anyone could authorize a routine purchase.','审批流程变得官僚刻板：工作人员先把同一数据抄到五份表格里，之后才有人能批准日常采购。','The approval process had become bureaucratic / staff copied the same data onto five forms / before anyone could authorize a routine purchase.','bureaucratic 作表语形容词；冒号后给出手续繁冗的表现。','重复填表、审批迟缓体现 s2 的繁琐规则义。')],mistakes:[m('The bureaucratic procedure required no forms, no officials, and immediate approval of every request.','The streamlined procedure required no forms, no officials, and immediate approval of every request.','无表格、无需官员且即时批准不符合繁琐官僚的 bureaucratic。')],quiz:[q('bureaucratic',1,2,'A bureaucratic process often involves?','too many rules, forms, or approval steps','no procedures or administration at all','a spontaneous outdoor game','bureaucratic 可带有手续繁复的含义。'),q('bureaucratic',2,1,'A bureaucratic office is most directly related to?','official administration and its procedures','wildlife behavior in a forest','a musical instrument','形容词也可中性指行政管理体系。'),q('bureaucratic',3,2,'Which complaint is bureaucratic?','“I must submit the same form to four offices.”','“The one-page form was approved immediately.”','“The clerk answered clearly in one minute.”','重复提交同一材料是程序繁冗。'),q('bureaucratic',4,1,'Choose the natural phrase.','bureaucratic paperwork','bureaucratic sunshine','a bureaucratic of offices','bureaucratic 可修饰 paperwork。')]});
D('bureaucratization',{etymology:e('bureaucratization 由 bureaucratize + -ation 构成，指组织逐步转为依赖正式官僚层级、规则与文书管理的过程。','bureaucratization'),contexts:[c('bureaucratization.s1','组织治理','The cooperative worried that bureaucratization would bury local decisions under layers of forms, so members kept neighborhood committees in control of small grants.','合作社担心官僚化会让层层表格淹没地方决策，因此让社区委员会继续管理小额拨款。','The cooperative worried / that bureaucratization would bury local decisions under layers of forms / so members kept neighborhood committees in control of small grants.','bureaucratization 作名词，指过程；that 从句作 worried 的宾语。','组织决策逐步被层级文书支配，体现官僚化过程。')],mistakes:[m('The group’s bureaucratization eliminated every formal office and returned all decisions to informal conversations.','The group’s decentralization eliminated formal offices and returned decisions to informal conversations.','取消官僚层级、回归非正式决策不是 bureaucratization。')],quiz:[q('bureaucratization',1,1,'Bureaucratization is the process by which an organization?','comes to rely more on formal offices, rules, and paperwork','removes all offices and formal procedures','changes its members into different species','bureaucratization 指组织逐渐官僚化的过程。'),q('bureaucratization',2,1,'Which change suggests bureaucratization?','more layers of approval and standardized forms','fewer procedures and greater local discretion','replacing a meeting room’s chairs','审批层级增多是官僚化迹象。'),q('bureaucratization',3,1,'The suffix -ization commonly names?','a process of making or becoming something','a person who sells furniture','a past-tense action only','-ization 常构成过程名词。'),q('bureaucratization',4,1,'A newspaper warns that bureaucratization may slow a group. It worries about?','growth of rule-bound administration','the loss of all written language','an increase in outdoor exercise','官僚化可能使组织行动变慢。')]});
D('burgeon',{etymology:e('burgeon 经古法语 bourgeonner“发芽、生出嫩枝”进入英语，源于表示花蕾的 bourgeon；可指植物发芽，也比喻迅速发展。','burgeon'),contexts:[c('burgeon.s2','城市发展','After the railway opened, small workshops burgeoned into a busy market district, and new cafés filled the streets near the station.','铁路开通后，小作坊迅速发展成繁忙的商业区，车站附近的街道也开起了许多新咖啡馆。','After the railway opened / small workshops burgeoned into a busy market district / and new cafés filled the streets near the station.','burgeon 作不及物动词；burgeon into 描述发展成某种规模。','商业区快速扩展，符合引申的迅速成长义 s2。')],mistakes:[m('The new industry burgeoned, shrinking from dozens of firms to one tiny workshop in a single week.','The new industry collapsed, shrinking from dozens of firms to one tiny workshop in a single week.','规模迅速缩小是衰退或崩溃，不是 burgeon。')],quiz:[q('burgeon',1,2,'A business that burgeons?','grows or develops rapidly','disappears before opening','remains exactly unchanged forever','burgeon 引申为迅速发展。'),q('burgeon',2,1,'In spring, a tree may burgeon by?','producing buds and fresh growth','losing its roots underground','turning into a stone','植物义指发芽并长出新枝。'),q('burgeon',3,2,'Which sentence uses burgeon figuratively?','New community groups burgeoned after the policy change.','The seed was sealed in a dry jar and never sprouted.','The street was empty and unchanged for years.','组织数量快速增加是比喻义。'),q('burgeon',4,2,'A market district burgeoned after a new station opened. It?','expanded quickly','was demolished immediately','remained undeveloped','burgeon 表示迅速成长或扩张。')]});
D('burger',{etymology:e('burger 是 hamburger 的截短形式；hamburger 源于 Hamburg“汉堡”及相关的汉堡牛肉饼称呼，burger 后来也用于其他夹饼。','burger'),contexts:[c('burger.s1','餐厅点餐','At the food truck, Luis ordered a bean burger on a toasted bun because he wanted a filling lunch without meat.','路易斯在餐车点了一份豆类汉堡，夹在烤面包胚里，因为他想吃一顿不含肉的饱腹午餐。','At the food truck / Luis ordered a bean burger on a toasted bun / because he wanted a filling lunch without meat.','burger 作可数名词；on a bun 表示夹在面包胚里。','豆类饼夹面包胚，是 burger 的非牛肉扩展用法。')],mistakes:[m('The menu lists a burger, but the dish is only a bowl of plain soup with no patty or bun.','The menu lists a soup, but the dish is only a bowl of plain soup with no patty or bun.','没有肉饼或夹馅面包的清汤不叫 burger。')],quiz:[q('burger',1,1,'A typical burger is served?','as a patty in a split bread roll','inside a drinking glass','as a bowl of dry flour','burger 通常是肉饼或替代饼夹在面包胚中。'),q('burger',2,1,'A veggie burger may use?','a plant-based patty','a whole roasted turkey only','a block of ice','素食汉堡可使用植物饼。'),q('burger',3,1,'The word burger is shortened from?','hamburger','burglar','burgundy','burger 是 hamburger 的截短形式。'),q('burger',4,1,'Which menu item is most likely a burger?','a grilled patty in a bun','a cup of black coffee','a plain spoonful of sugar','肉饼夹面包胚符合 burger。')]});
D('burgess',{etymology:e('burgess 经古法语 burgeis 源于 burg/burh“城镇、堡垒”，历史上指享有城镇权利的居民或代表该城镇的议员。','burgess'),contexts:[c('burgess.s1','中世纪市镇','The charter granted each burgess a vote in the town assembly, along with the right to trade at the protected weekly market.','特许状赋予每位城镇自由民在镇议会投票的权利，也允许他们在受保护的周市交易。','The charter granted each burgess a vote in the town assembly / along with the right to trade / at the protected weekly market.','burgess 作历史身份名词；grant sb a vote 表示授予投票权。','享有市镇权利并参与地方议事，符合历史词义。')],mistakes:[m('The medieval burgess had no town rights and was barred from every local assembly by definition.','The medieval outsider had no town rights and was barred from the local assembly.','burgess 历史上指拥有市镇身份或权利的居民/代表，而非没有权利者。')],quiz:[q('burgess',1,1,'Historically, a burgess was associated with?','a town and its civic rights','a ship’s engine room','an isolated mountain glacier','burgess 是享有城镇身份权利的居民。'),q('burgess',2,1,'A burgess might have been sent to?','represent a town in a legislative assembly','repair the king’s shoes','measure ocean salinity','burgess 也可指城镇的代表议员。'),q('burgess',3,1,'Which right fits a medieval burgess?','trading at the town market under its charter','entering every private home','ignoring all civic rules','市镇特许权可能包括在市场贸易。'),q('burgess',4,1,'The word is chiefly?','historical in its civic sense','a modern term for a kitchen tool','a verb meaning to swim','burgess 的市民/议员义主要见于历史语境。')]});
D('burgher',{etymology:e('burgher 源自中古荷兰语或德语 burger，来自 burg“城镇、堡垒”，指城镇居民；历史上也可指较富裕的市民或商人。','burgher'),contexts:[c('burgher.s1','欧洲城市史','The museum exhibit follows a prosperous burgher who financed the guild hall, traded cloth across the region, and served on the town council.','博物馆展览介绍一位富裕市民：他出资建造行会会堂，在各地经营布匹贸易，并担任镇议会成员。','The museum exhibit follows a prosperous burgher / who financed the guild hall / traded cloth across the region / and served on the town council.','burgher 作历史名词；who 引导描述该城镇市民的定语从句。','富裕城镇居民、商人和议事者符合历史用法。')],mistakes:[m('The medieval burgher lived alone in a forest with no connection to any town or civic life.','The medieval hermit lived alone in a forest with no connection to any town or civic life.','burgher 与城镇居民身份相关；离群隐居者是 hermit。')],quiz:[q('burgher',1,1,'A historical burgher was a?','citizen or inhabitant of a town','sailor who never reached land','person who lived only in a cave','burgher 指城镇公民或居民。'),q('burgher',2,1,'In some historical contexts, a burgher was especially?','a comfortable merchant or prosperous townsman','a wandering sea creature','a royal kitchen utensil','该词有时特指富裕市民或商人。'),q('burgher',3,1,'Which person best fits burgher?','a town trader who takes part in civic affairs','a hermit who avoids every settlement','a wild animal in a forest','参与城镇生活的商人符合 burgher。'),q('burgher',4,1,'The element burg in burgher refers to?','a town or fortified settlement','a type of fruit','the act of writing','词源中的 burg 与城镇有关。')]});
D('burin',{etymology:e('burin 经法语 burin 借入英语，指带尖锐切削端、供雕刻金属或木版图案的钢制工具；更早词源不确定。','burin'),contexts:[c('burin.s1','版画制作','The engraver used a burin to cut fine parallel lines into the copper plate, checking each groove under a magnifying lens before printing.','雕刻师用钢凿在铜版上刻出细密平行线，并在印刷前用放大镜检查每条凹槽。','The engraver used a burin to cut fine parallel lines into the copper plate / checking each groove under a magnifying lens / before printing.','burin 作可数工具名；to cut 表示使用工具的目的。','钢制尖刻工具在铜版上刻线，符合 burin 义。')],mistakes:[m('The printmaker used a soft paintbrush as a burin to cut deep grooves into the copper plate.','The printmaker used a steel engraving tool as a burin to cut deep grooves into the copper plate.','burin 是钢制刻刀而不是柔软画笔。')],quiz:[q('burin',1,1,'A burin is used to?','cut designs into metal or wood','stir soup in a pot','measure a room’s temperature','burin 是用于雕刻图案的工具。'),q('burin',2,1,'An engraver working on copper may hold a?','burin','bread basket','rain gauge','刻铜版时会使用 burin。'),q('burin',3,1,'What makes a burin suitable for engraving?','its sharp cutting point','a soft sponge tip','a hollow bowl','尖锐刃端能切刻线条。'),q('burin',4,1,'Which craft worker is most likely to use a burin?','a printmaker engraving a plate','a baker kneading dough','a swimmer practicing strokes','版画雕刻师会用 burin。')]});
D('burning',{etymology:e('burning 是 burn 的 -ing 形式；可作形容词指正在燃烧，也可指强烈情绪，还可作名词指燃烧过程。','burning'),contexts:[c('burning.s3','消防调查','Investigators documented the burning of the warehouse, noting how quickly the fire spread after an electrical fault ignited stored cardboard.','调查人员记录了仓库起火燃烧的过程，指出电气故障点燃存放的纸板后火势蔓延得很快。','Investigators documented the burning of the warehouse / noting how quickly the fire spread / after an electrical fault ignited stored cardboard.','burning 作名词，of 引出燃烧对象；after 引出点燃原因。','叙述火灾发生和蔓延过程，符合名词义 s3。')],mistakes:[m('The burning of the building involved no fire, heat, or combustion of any material.','The evacuation of the building involved no fire, heat, or combustion of any material.','没有火或燃烧过程就不能称 burning。')],quiz:[q('burning',1,1,'A burning log is?','producing flames and heat','frozen solid in ice','made only of water','形容词义 burning 表示正在燃烧。'),q('burning',2,2,'A burning ambition is?','an extremely strong desire','a piece of cold metal','a weak passing preference','比喻义表示强烈愿望。'),q('burning',3,3,'The burning of fuel refers to?','the process of combustion','the act of freezing it','a method of weighing it','名词 burning 指燃烧过程。'),q('burning',4,2,'A burning question is one that?','feels urgent and demands an answer','has already lost all importance','is asked only near a fire','burning 可比喻问题紧迫、亟待回答。')]});
D('burnish',{etymology:e('burnish 经古法语 burnir“磨光、擦亮”进入英语，指摩擦金属或木材使表面光滑发亮；也可比喻改善形象或技能。','burnish'),contexts:[c('burnish.s1','金属工艺','The silversmith burnished the bowl with a smooth steel tool until its dull surface reflected the workshop lights.','银匠用光滑钢工具擦亮碗，直到原本暗淡的表面映出工坊灯光。','The silversmith burnished the bowl with a smooth steel tool / until its dull surface reflected the workshop lights.','burnish 作及物动词；until 引出擦拭达到的结果。','摩擦金属直到发亮，符合物理义 s1。')],mistakes:[m('The silversmith burnished the silver until its surface became rough, dull, and less reflective.','The silversmith scratched the silver until its surface became rough, dull, and less reflective.','burnish 是擦亮光滑，不是刮粗刮暗；scratched 才符合。')],quiz:[q('burnish',1,1,'To burnish a metal bowl is to?','rub it smooth and shiny','paint it with thick mud','bend it into a different shape','burnish 指摩擦金属使之光滑发亮。'),q('burnish',2,2,'A candidate may burnish a public image by?','working to improve how the public sees them','hiding every achievement','breaking all campaign promises','比喻义指改善形象或声誉。'),q('burnish',3,1,'Which tool might burnish silver?','a smooth polishing tool','a rough saw blade','a wet paper towel used to erase ink','抛光工具可擦亮银器。'),q('burnish',4,1,'Choose the natural use.','She burnished the table until the wood gleamed.','She burnished the soup until it boiled.','She burnished a hole by digging it deeper.','burnish 可用于擦亮木材表面。')]});
D('bushel',{etymology:e('bushel 经古法语 boissel、拉丁语与古法语量器名称进入英语，传统干量等于八加仑；另有旧式服装业动词，指改衣或缝短衣物。','bushel'),contexts:[c('bushel.s1','粮食贸易','The farmer sold a bushel of wheat at the market, and the buyer checked the standard measure before loading the grain onto a cart.','农民在市场卖出一蒲式耳小麦，买家在把谷物装上车前核对了标准量器。','The farmer sold a bushel of wheat at the market / and the buyer checked the standard measure / before loading the grain onto a cart.','bushel 作计量单位；a bushel of 后接谷物名。','小麦按传统干量单位交易，符合 s1。')],mistakes:[m('The market sold one bushel of wheat by measuring exactly eight gallons of liquid milk.','The market sold one bushel of wheat by measuring the grain with a dry-volume measure.','bushel 是谷物等干货的容量单位，不是液态牛奶的标准量。')],quiz:[q('bushel',1,1,'A bushel traditionally measures?','dry goods such as grain','the temperature of a furnace','the length of a river','bushel 是谷物等干货的传统容量单位。'),q('bushel',2,2,'In an old tailoring sense, to bushel a garment is to?','alter or shorten it','fill it with grain','weigh it on a farm scale','旧式 bushel 可指改衣、缝短衣物。'),q('bushel',3,1,'Which sale might be quoted in bushels?','a quantity of corn','one liter of cooking oil','a dozen metal screws by length','谷物可按蒲式耳计量。'),q('bushel',4,1,'In the traditional system, one bushel equals?','eight gallons of dry measure','one inch','a hundred pounds of water','传统蒲式耳等于八加仑干量。')]});
D('bushman',{etymology:e('bushman 由 bush + man 构成，指熟悉或居住于偏远丛林地带的人，尤见于澳大利亚英语；具体称呼需结合地区语境。','bushman'),contexts:[c('bushman.s1','澳大利亚内陆','The bushman knew where seasonal creeks crossed the cattle route, so he guided the survey team around the dry flats before nightfall.','这位熟悉澳大利亚内陆丛林地区的人知道季节性溪流在哪里穿过牧牛路线，因此赶在天黑前带测量队绕过干燥低地。','The bushman knew where seasonal creeks crossed the cattle route / so he guided the survey team / around the dry flats before nightfall.','bushman 指熟悉 bush 地区的人；where 引导 know 的宾语从句。','对偏远内陆地形熟悉并带路，符合词条义。')],mistakes:[m('The bushman had never left a city office and knew nothing about the remote bush.','The city clerk had never left a city office and knew nothing about the remote bush.','不熟悉荒野地区的人不能以此义称 bushman。')],quiz:[q('bushman',1,1,'An Australian bushman is likely to know?','the remote bush country and its conditions','the underwater trenches of the Atlantic only','the rules of a city chess club only','bushman 指熟悉偏远 bush 地区的人。'),q('bushman',2,1,'Who might guide cattle across remote scrubland?','a bushman','a subway conductor','a deep-sea diver','熟悉内陆地形的人可带牧牛路线。'),q('bushman',3,1,'The element bush in bushman refers to?','remote uncultivated country','a kitchen cabinet','a flowering houseplant only','bush 在澳大利亚语境指偏远荒野地带。'),q('bushman',4,1,'Which context best fits the word?','an experienced local guiding travelers through the outback','a clerk filing papers in a downtown office','a pilot landing on the moon','内陆荒野经验符合 bushman。')]});
D('businesswoman',{etymology:e('businesswoman 由 business + woman 构成，指从事商业活动的女性，尤其可指经营企业或担任商业管理职位的人。','businesswoman'),contexts:[c('businesswoman.s1','创业经营','The businesswoman negotiated a supply contract for her company, then met with the staff to explain how the new schedule would affect deliveries.','这位女商人替公司谈妥供货合同，随后与员工会面，解释新排班如何影响配送。','The businesswoman negotiated a supply contract for her company / then met with the staff / to explain how the new schedule would affect deliveries.','businesswoman 作职业名词；to explain 表示会面的目的。','谈判合同并管理公司运营符合商业女性这一职业义。')],mistakes:[m('The businesswoman never took part in commerce, management, or any professional activity.','The businesswoman led the company’s commercial operations and negotiated with suppliers.','完全不参与商业活动与 businesswoman 的定义相反。')],quiz:[q('businesswoman',1,1,'A businesswoman is a woman who?','works in or manages commercial activity','is defined only by her cooking skills','never takes part in work','businesswoman 指从事商业活动的女性。'),q('businesswoman',2,1,'Which task might a businesswoman perform?','negotiate a contract with a supplier','identify a bird by its song as her only role','repair a bridge with no business connection','合同谈判属于商业经营活动。'),q('businesswoman',3,1,'The word combines business with?','woman','wood','water','businesswoman 由 business 与 woman 组成。'),q('businesswoman',4,1,'Which sentence uses the word naturally?','The businesswoman opened a second branch downtown.','The businesswoman is a type of freight train.','The businesswoman of the river flowed uphill.','开设分店符合商业经营语境。')]});
D('butler',{etymology:e('butler 经古法语 bouteillier“酒窖/酒瓶管理员”进入英语，源自 bouteillier 与酒瓶相关；后来指负责大户人家服务人员及家务管理的管家。','butler'),contexts:[c('butler.s1','庄园服务','The butler greeted the guests at the entrance, coordinated the household staff, and made sure dinner was served at the announced hour.','管家在入口迎接客人、协调家务人员，并确保晚餐按宣布的时间上桌。','The butler greeted the guests at the entrance / coordinated the household staff / and made sure dinner was served at the announced hour.','butler 作主语名词；并列谓语说明其家务管理职责。','迎宾、协调仆役并安排用餐体现主男性管家的职责。')],mistakes:[m('The butler managed the household staff and served dinner, but the household had no domestic service or table service.','The caretaker managed the building staff and arranged its maintenance, but the household had no domestic service or table service.','管家负责家庭内务和餐桌服务；纯建筑维护更接近 caretaker。')],quiz:[q('butler',1,1,'A butler traditionally manages?','a household’s domestic staff and formal service','a ship’s navigation equipment','a farm’s crop rotation only','butler 是管理家务人员和服务的管家。'),q('butler',2,1,'At a formal dinner, a butler may?','coordinate service for the household','repair the guests’ cars as the only duty','write the city’s tax code','管家通常协调正式家务与餐桌服务。'),q('butler',3,1,'Which person best fits butler?','the senior male servant overseeing household staff','a visitor who comes for one meal','a machine that washes dishes','butler 指家庭中的资深男性管家。'),q('butler',4,1,'Historically, the word first related to a person in charge of?','bottles or wine service','horse shoeing','printing maps','butler 的早期词源与酒瓶管理有关。')]});
D('butte',{etymology:e('butte 借自法语 butte“土丘、小山”，在英语尤其指西部地貌中孤立、陡壁明显且顶部较平的小山。','butte'),contexts:[c('butte.s1','地貌考察','The isolated butte rose above the plain, its steep sides exposing layers of rock while a relatively flat cap remained at the summit.','这座孤立的小山从平原上突起，陡坡露出层层岩石，顶部则保留着相对平坦的岩层。','The isolated butte rose above the plain / its steep sides exposing layers of rock / while a relatively flat cap remained at the summit.','butte 作地貌名词；while 对比陡峭山侧与平顶。','孤立、陡侧和平顶的地貌特征符合 butte。')],mistakes:[m('The butte was a broad flat valley with no hill rising above the surrounding plain.','The butte was a steep-sided isolated hill rising above the surrounding plain.','butte 是突起的小山，不是低洼山谷。')],quiz:[q('butte',1,1,'A butte is typically?','an isolated steep-sided hill with a fairly flat top','a broad valley below sea level','a deep ocean current','butte 指孤立陡壁、顶部较平的小山。'),q('butte',2,1,'A geologist might study a butte to examine?','exposed rock layers on its sides','the inside of a living cell only','how clouds are printed on paper','陡坡上的岩层便于地质观察。'),q('butte',3,1,'Which landform best matches butte?','a lone mesa-like hill above a plain','a flat meadow with no rise','a narrow underground tunnel','孤立突起的平顶山符合 butte。'),q('butte',4,1,'The word butte entered English from?','French','Japanese','Swahili','butte 源自法语小山一词。')]});
D('buzzer',{etymology:e('buzzer 由 buzz（发出嗡嗡声）加施事者/器具后缀 -er 构成，指用嗡鸣声提醒、召唤或计时的装置。','buzzer'),contexts:[c('buzzer.s1','知识竞赛','At the quiz show, each contestant pressed a buzzer to signal an answer, and the host recognized the first clear tone before reading the next question.','知识竞赛中，每位选手按下蜂鸣器表示作答，主持人听清最先响起的信号后才读下一题。','At the quiz show / each contestant pressed a buzzer to signal an answer / and the host recognized the first clear tone / before reading the next question.','buzzer 作按键式提示设备；to signal 表示按下按钮的目的。','用蜂鸣声提示选手作答，符合器具义。')],mistakes:[m('The buzzer was silent and gave no sound or signal when anyone pressed it.','The broken buzzer was silent and gave no sound or signal when anyone pressed it.','正常 buzzer 会发出嗡鸣；若无声需说明设备损坏。')],quiz:[q('buzzer',1,1,'A buzzer is a device that?','makes a buzzing sound to signal someone','measures a room’s length','stores food at low temperature','buzzer 是用嗡鸣提醒的装置。'),q('buzzer',2,1,'A contestant presses a buzzer to?','signal that they are ready to answer','turn a page silently','switch off the television permanently','按蜂鸣器可发出作答信号。'),q('buzzer',3,1,'A door buzzer may be used to?','alert someone that a visitor has arrived','cool a room in summer','print an address label','门铃式 buzzer 可提示有人来访。'),q('buzzer',4,1,'The ending -er in buzzer names?','a device that produces a buzz','a person who is always asleep','a place where bread grows','-er 在这里构成发声器具名词。')]});
D('by-pass',{etymology:e('by-pass 是 by + pass 构成的拼写变体，通常也写 bypass；名词可指绕城公路或医学旁路，动词指绕过地点、程序或障碍。','by-pass'),contexts:[c('by-pass.s2','办事流程','Rather than by-pass the safety review, the engineer submitted the design through the required inspection process and documented each change.','工程师没有绕过安全审查，而是按规定把设计提交检查，并记录每一项改动。','Rather than by-pass the safety review / the engineer submitted the design through the required inspection process / and documented each change.','by-pass 在此作动词，表示绕开程序；rather than 后接动词原形。','句子涉及绕过审查流程，符合动词义 s2。')],mistakes:[m('The engineer bypassed no safety checks and still claimed that the design had avoided every required review.','The engineer completed the safety checks instead of bypassing the required review.','完成全部审查与“绕过审查”相矛盾；须改为遵守流程。')],quiz:[q('by-pass',1,1,'A town by-pass is a road designed to?','carry traffic around the built-up center','lead every vehicle through the town square','connect two rooms in a house','by-pass 公路绕开城镇中心。'),q('by-pass',2,2,'To by-pass a rule means to?','avoid or go around it','follow it exactly','write it in a larger font','动词义表示规避规则。'),q('by-pass',3,1,'A cardiac by-pass is related to?','routing blood around a blocked vessel','building a road around a village','skipping the opening chapter of a book','医学名词 by-pass 指血流旁路。'),q('by-pass',4,2,'Which action is a by-pass of procedure?','going around a required approval step','submitting the form to the correct office','waiting for the official review','跳过规定审批步骤是绕开流程。')]});
D('by-product',{etymology:e('by-product 由 by + product 构成，字面为伴随主要产物而来的次要产物，也引申为非预期结果；连字符写法与 byproduct 并用。','by-product'),contexts:[c('by-product.s1','制造流程','The recycling plant sells recovered heat as a by-product of turning waste into electricity, so less energy is lost during production.','回收厂把废物转化为电力时产生的余热作为副产品出售，因此减少了生产过程中的能源损失。','The recycling plant sells recovered heat as a by-product of turning waste into electricity / so less energy is lost during production.','by-product 作名词；of 后说明副产品伴随的主要生产过程。','余热伴随发电过程产生，符合次要产物义。')],mistakes:[m('The factory’s main product was called a by-product even though it was the sole intended output and no secondary result existed.','The factory’s sole intended output was called its main product, not a by-product.','by-product 是伴随主要产品的次要或副产结果，不是唯一主要产物。')],quiz:[q('by-product',1,1,'A by-product is?','a secondary result of a main process','the only intended output of a factory','a product bought before it is made','by-product 指主要过程带来的次要产物。'),q('by-product',2,1,'Recovered heat may be a by-product of?','generating electricity','a silent reading lesson','a road sign being painted','热量可作为发电时的副产结果。'),q('by-product',3,1,'Stress can be an unintended by-product of?','a demanding schedule','a deliberate gift card','a completed shopping list','非预期的压力可能是繁忙日程的副作用。'),q('by-product',4,1,'Which spelling is also used for the same word?','byproduct','buyproduct','byproducts only as a verb','byproduct 是不带连字符的拼写变体。')]});
D('bygone',{etymology:e('bygone 由 by + gone 组合，字面指已经过去的事物或时期；可作形容词，也常在 let bygones be bygones 中作复数名词。','bygone'),contexts:[c('bygone.s2','和解对话','After they apologized for the old argument, both cousins agreed to let bygones be bygones and plan a new family visit.','为过去的争执道歉后，两位堂兄妹同意不再计较旧事，并计划一次新的家庭探访。','After they apologized for the old argument / both cousins agreed to let bygones be bygones / and plan a new family visit.','固定表达 let bygones be bygones 中 bygones 是复数名词。','双方放下过去的旧事，符合名词义 s2。')],mistakes:[m('Let bygones be bygones means keeping every old grievance active and refusing to move on.','Let bygones be bygones means forgiving old grievances and moving on.','该习语是放下旧怨，而非持续纠缠旧事。')],quiz:[q('bygone',1,1,'A bygone era is?','a period that has passed','a period that has not yet begun','a time lasting only one second','bygone 作形容词指过去的时期。'),q('bygone',2,2,'In “let bygones be bygones,” bygones are?','past quarrels or events people agree to leave behind','future plans that have not been made','rules that must be enforced','该习语中的 bygones 指过去的旧事或旧怨。'),q('bygone',3,1,'Which is a natural phrase?','a reminder of bygone days','a prediction of bygone tomorrow','one bygones event','bygone days 是常见搭配。'),q('bygone',4,2,'When people let bygones be bygones, they?','stop holding old disagreements against one another','repeat the same argument each morning','publish a list of new rules','他们放下过去争执并继续相处。')]});
D('bylaw',{etymology:e('bylaw 由古诺斯语或古英语相关形式构成，by- 在早期用于“城镇/地方”语境，law 为法律，原指地方性规章，现指机构或地方政府制定的附属法规。','bylaw'),contexts:[c('bylaw.s1','社区治理','The neighborhood bylaw limits overnight construction noise, and the council can issue a warning when a contractor ignores the quiet hours.','社区附例限制夜间施工噪音；承包商无视安静时段时，市议会可以发出警告。','The neighborhood bylaw limits overnight construction noise / and the council can issue a warning / when a contractor ignores the quiet hours.','bylaw 作可数名词；when 引导违规情况下的后果。','地方社区规章规范施工时间，符合附属地方条例义。')],mistakes:[m('The council passed a bylaw that had the force of the nation’s constitution and overruled all national laws.','The council passed a local bylaw governing construction noise within its jurisdiction.','bylaw 是地方或组织层级规章，通常不高于国家法律。')],quiz:[q('bylaw',1,1,'A bylaw is typically made by?','a local council or organization','the weather','a private shopper for personal use','bylaw 常由地方政府、公司或社团制定。'),q('bylaw',2,1,'A club bylaw might regulate?','how members elect officers','the orbit of Mars','the spelling of every language worldwide','社团附例可规定成员选举办法。'),q('bylaw',3,1,'A bylaw usually ranks below?','general national law','a handwritten shopping note','a person’s favorite color','地方附例的层级低于一般国家法律。'),q('bylaw',4,1,'Which topic could a town bylaw address?','quiet hours for local construction','the chemistry of distant stars','the private thoughts of visitors','地方政府可管理辖区内施工时段。')]});
D('byline',{etymology:e('byline 由 by + line 构成，指印在文章或新闻报道旁、标明作者姓名的署名行。','byline'),contexts:[c('byline.s1','新闻出版','The online report carried a byline naming reporter Mina Chen, while the editor’s note below it explained how the investigation was conducted.','这篇网络报道附有署名行，标出记者陈米娜的姓名；下方的编辑说明则解释了调查方法。','The online report carried a byline naming reporter Mina Chen / while the editor’s note below it explained how the investigation was conducted.','byline 作可数名词；naming 分词说明署名行列出谁的名字。','标注新闻作者姓名的行是 byline。')],mistakes:[m('The article’s byline hid the writer’s name and showed only the paper’s weather forecast.','The article’s headline showed its topic, while the byline named the writer.','作者署名行要标作者姓名；主题标题或天气预报不是 byline。')],quiz:[q('byline',1,1,'A newspaper byline tells readers?','who wrote the article','what the article’s main headline says only','when the paper was printed','byline 用于标示作者姓名。'),q('byline',2,1,'Where might a reader find a byline?','near the title of a news story','inside a building’s foundation','on the underside of a shoe','署名行通常出现在新闻标题附近。'),q('byline',3,1,'Which line is a byline?','“By Lena Ortiz, staff reporter”','“Storm closes three roads”','“Page 4 of 12”','“By …”列出作者身份，是署名行。'),q('byline',4,1,'A report without a byline does not clearly identify?','its author','its paper size','the day’s temperature','byline 的作用是注明作者。')]});
D('byproduct',{etymology:e('byproduct 是 by + product 的合成写法，与 by-product 同义，指主要流程伴生的次要产物或非预期结果。','byproduct'),contexts:[c('byproduct.s1','工业材料','Sulfur was captured as a byproduct of the refining process and sent to a nearby plant that could use it in manufacturing.','硫磺作为炼制过程的副产物被回收，并送往附近一家可将其用于制造业的工厂。','Sulfur was captured as a byproduct of the refining process / and sent to a nearby plant / that could use it in manufacturing.','byproduct 作名词；of 后说明副产物所伴随的主要流程。','硫磺是在炼制过程中伴生并被回收的产物。')],mistakes:[m('The refinery called its sole planned output a byproduct even though it produced nothing else.','The refinery called its sole planned output its main product because it produced nothing else.','只有一个计划中的产物时，应称主要产品，不是副产物。')],quiz:[q('byproduct',1,1,'A byproduct is produced?','alongside a main product or process','before any process begins','only as the primary intended output','byproduct 是伴随主要过程产生的次要结果。'),q('byproduct',2,1,'Which may be a byproduct of food production?','usable plant material left after processing','the only ingredient purchased at a shop','a recipe written before harvest','加工剩余的可用植物材料可能是副产物。'),q('byproduct',3,1,'The spelling byproduct is equivalent to?','by-product','buy product','byproducted','byproduct 与 by-product 同义。'),q('byproduct',4,1,'If noise is an unwanted byproduct of construction, it is?','an unintended side effect','the only goal of the project','a required building material','不想要的噪音是施工带来的副作用。')]});
D('cabal',{etymology:e('cabal 经法语 cabale、拉丁语 cabala 借入，最终关联希伯来语 qabbalah；“秘密小集团”义为后来的政治用法，不应照搬关于英文内阁姓名首字母的民间词源故事。','cabal'),contexts:[c('cabal.s1','政治传闻','The minister denied that a cabal was secretly controlling the council, saying that every major decision had been recorded in public minutes.','部长否认有秘密小集团暗中控制市议会，并表示所有重大决定都记录在公开会议纪要中。','The minister denied that a cabal was secretly controlling the council / saying that every major decision had been recorded in public minutes.','cabal 作可数名词；that 从句作 denied 的宾语。','秘密操纵权力的小集团符合名词义 s1。')],mistakes:[m('The cabal announced its membership publicly, held open elections, and published every plan before acting.','The association announced its membership publicly, held open elections, and published every plan before acting.','公开透明且民主运作的协会不符合 cabal 所含秘密结党意味。')],quiz:[q('cabal',1,1,'A political cabal is?','a small secret group plotting for influence','an elected body conducting all meetings openly','a public library committee with no political role','cabal 指秘密策划以获取影响力的小集团。'),q('cabal',2,2,'To cabal means to?','plot together in a small secret group','publish all decisions openly','build a cabin beside a lake','动词 cabal 指秘密结党策划。'),q('cabal',3,1,'Which situation suggests a cabal?','a few officials secretly coordinating a power grab','residents openly voting on a published proposal','a teacher assigning a public reading list','秘密协调夺权符合 cabal 的含义。'),q('cabal',4,1,'A cabal’s plans are usually?','secret or concealed','posted for everyone before discussion','unrelated to influence or plotting','秘密性是 cabal 的核心特征。')]});
D('cabinetmaker',{etymology:e('cabinetmaker 由 cabinet + maker 构成，指制作精细柜橱等家具的木工；cabinet 源于法语 cabine 一类小房间/箱柜词。','cabinetmaker'),contexts:[c('cabinetmaker.s1','家具制作','The cabinetmaker selected a straight-grained walnut board, cut precise joints, and fitted the doors so the finished cabinet would close evenly.','橱柜木匠选了一块纹理笔直的胡桃木板，切出精确接榫并安装柜门，让成品柜门闭合平整。','The cabinetmaker selected a straight-grained walnut board / cut precise joints / and fitted the doors / so the finished cabinet would close evenly.','cabinetmaker 作职业名词；并列动词描述木工制作流程。','制作精细橱柜和柜门是该工匠的职业。')],mistakes:[m('The cabinetmaker designed a cabinet but never shaped wood or assembled any furniture.','The furniture designer designed a cabinet but never shaped wood or assembled any furniture.','cabinetmaker 通常亲手制作家具；只负责设计而不制作可称设计师。')],quiz:[q('cabinetmaker',1,1,'A cabinetmaker specializes in?','building fine cabinets and other furniture','writing tax regulations','repairing a ship’s engine only','cabinetmaker 指制作柜橱家具的木工。'),q('cabinetmaker',2,1,'Which tools might a cabinetmaker use?','saws, chisels, and woodworking clamps','stethoscopes and thermometers','fishing nets and buoys','木工常用锯、凿和夹具制作家具。'),q('cabinetmaker',3,1,'A cabinetmaker is most likely to shape?','wood for a fitted cupboard','a cloud into a metal frame','a legal contract into a musical instrument','柜橱常由木工制作。'),q('cabinetmaker',4,1,'The compound names someone who makes?','cabinets','cabins for ships only','cabinets’ legal rules','cabinetmaker 字面是制作柜橱的人。')]});
D('cacophony',{etymology:e('cacophony 源自希腊语 kakophōnia，由 kakos“坏的”与 phōnē“声音”构成，经拉丁语进入英语，指刺耳、不和谐的杂音。','cacophony'),contexts:[c('cacophony.s1','城市街道','A cacophony of horns, reversing alarms, and shouted directions filled the narrow street while delivery trucks tried to unload at once.','送货卡车同时卸货时，狭窄街道上充满喇叭、倒车警报和喊叫声交织成的刺耳杂音。','A cacophony of horns, reversing alarms, and shouted directions filled the narrow street / while delivery trucks tried to unload at once.','cacophony 作名词；of 后列举构成杂音的声音。','多种嘈杂刺耳声同时响起，符合词义。')],mistakes:[m('The cacophony was a single soft flute note played in perfect harmony with complete silence.','The melody was a single soft flute note played clearly above the background silence.','单一柔和且和谐的音符不是 cacophony。')],quiz:[q('cacophony',1,1,'A cacophony is?','a harsh mixture of unpleasant sounds','one clear, harmonious note','a silent written message','cacophony 指刺耳的混杂噪音。'),q('cacophony',2,1,'Which setting might produce a cacophony?','a busy street with horns and alarms sounding together','a quiet room during a pause','a library where no one speaks','多种喇叭和警报同时响会形成噪声。'),q('cacophony',3,1,'The Greek elements in cacophony point to?','bad sound','green leaf','small town','kakos + phone 意为坏的声音。'),q('cacophony',4,1,'Which is the opposite of a cacophony?','a clear, harmonious melody','a jumble of clashing alarms','a crowd shouting over one another','和谐旋律与刺耳杂音相反。')]});
D('cacti',{etymology:e('cacti 是 cactus 的传统拉丁式复数；现代英语也常用规则复数 cactuses。','cacti'),contexts:[c('cacti.s1','植物园导览','The greenhouse displayed cacti from several dry regions, with labels explaining how their spines help protect water-storing stems.','温室展出来自多个干旱地区的仙人掌，标签说明它们的刺如何保护储水茎。','The greenhouse displayed cacti from several dry regions / with labels explaining / how their spines help protect water-storing stems.','cacti 是 cactus 的复数名词；their 指代这些植物。','多种仙人掌的集合使用传统复数 cacti。')],mistakes:[m('Several cacti is growing in the greenhouse, each in a separate pot.','Several cacti are growing in the greenhouse, each in a separate pot.','复数主语 cacti 应搭配 are，而不是 is。','grammar')],quiz:[q('cacti',1,1,'Cacti means?','more than one cactus','one cactus only','a room for growing vegetables','cacti 是 cactus 的复数形式。'),q('cacti',2,1,'Which sentence has correct subject–verb agreement?','The cacti are flowering.','The cacti is flowering.','A cacti are flowering.','复数主语 cacti 与 are 搭配。'),q('cacti',3,1,'Which is also a standard plural of cactus?','cactuses','cactusen','cactis','英语中 cactuses 也是常见规则复数。'),q('cacti',4,1,'A botanist counting several desert cacti is counting?','multiple spiny succulent plants','one watering can','a type of flower pot','cacti 指多株仙人掌。')]});
D('cactus',{etymology:e('cactus 借自拉丁语 cactus，源自希腊语 kaktos“带刺的植物”；泛指适应干旱环境、通常有刺的多肉植物。','cactus'),contexts:[c('cactus.s1','沙漠植物','The cactus stored water in its thick stem, allowing it to survive long dry periods on the rocky desert slope.','这株仙人掌把水储存在粗壮的茎中，因此能在多岩石的沙漠山坡上熬过漫长旱季。','The cactus stored water in its thick stem / allowing it to survive long dry periods / on the rocky desert slope.','cactus 作可数名词；allowing 分词短语说明储水带来的结果。','粗茎储水并适应旱地，符合仙人掌义。')],mistakes:[m('The cactus thrived underwater in a freshwater tank because its leaves were broad and unprotected from water loss.','The water lily thrived underwater in a freshwater tank because its leaves were broad and adapted to aquatic life.','仙人掌适应干燥环境；长期水下生长适合水生植物而非 cactus。')],quiz:[q('cactus',1,1,'A cactus is adapted especially to?','dry environments where water is limited','permanent life deep underwater','cold ocean trenches with no sunlight','仙人掌通常适应干旱环境。'),q('cactus',2,1,'Which feature helps many cacti conserve water?','a thick water-storing stem and spines','large thin leaves that lose water quickly','gills for extracting oxygen underwater','仙人掌以茎储水，刺可替代叶片防护。'),q('cactus',3,1,'Which is a correct plural form of cactus?','cacti','cactuseses','cactis only','cacti 是传统复数，cactuses 也正确。'),q('cactus',4,1,'Where is a cactus most likely to grow naturally?','a dry rocky desert','a permanently flooded pond','a dark ocean trench','沙漠环境适合仙人掌。')]});

})();
